DROP FUNCTION OS_CLAIM_BY_DETAIL_BY_RATECODE

GO

CREATE FUNCTION OS_CLAIM_BY_DETAIL_BY_RATECODE( @P_EDate as  smalldatetime)                          
RETURNS TABLE                           
AS RETURN (                          

--Current Reserve
SELECT                          
 CLAIM.OCNO, CLAIM.PAYMENT, CLAIM.ANO, CLAIM.CNO, LCALC.CODE, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, Currency.Rate, CLAIM.ISTYPE, CLAIM.CLAIMNO,                    
    
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)-(0)                          
  ELSE                          
    ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)-((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)                        
  END                          
 end) as GROSS_OS,        

