  ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EXPAMOUNT/CH.ETAMOUNT ELSE 0 END)
