 end) as EXPENSE_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.TCOST-PCCALC.COST-PCCALC.RCOST)) ELSE 0 END)                          
  ELSE                          
    (0)                        
  END                          
 end) as EXPENSE_SETTLED,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (0)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    ((0)-CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSUBROGATION-PCCALC.SUBROGATION-PCCALC.RSUBROGATION)) ELSE 0 END)                          
  ELSE                          
    (0)-(0)                        
  END                          
 end) as OWNSUBROGATION_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    (CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSUBROGATION-PCCALC.SUBROGATION-PCCALC.RSUBROGATION)) ELSE 0 END)                          
  ELSE                          
    (0)                        
  END                          
 end) as OWNSUBROGATION_SETTLED,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (0)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    ((0)-CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSALVAGE-PCCALC.SALVAGE-PCCALC.RSALVAGE)) ELSE 0 END)                          
  ELSE                          
    (0)-(0)                        
  END                          
 end) as OWNSALVAGE_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    (CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSALVAGE-PCCALC.SALVAGE-PCCALC.RSALVAGE)) ELSE 0 END)                          
  ELSE                          
    (0)                        
  END                          
 end) as OWNSALVAGE_SETTLED,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (0)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (0)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.CLAIM)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
    (0)-(0)                        
  END                          
 end) as LOSS_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.CLAIM)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
   (0)                        
  END                          
 end) as LOSS_Settled, 
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (0)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (0)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((-PCCALC.DEDUCTIBLE)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
    (0)-(0)                        
  END                          
 end) as DEDUCTIBLE_OS,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((-PCCALC.DEDUCTIBLE)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
    (0)                        
  END                          
 end) as DEDUCTIBLE_Settled,
 
  (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  -(0)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   -(0)+(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.SALVAGE)*PCCALC.SHARE/100+PCCALC.RSALVAGE) ELSE 0 END)                          
  ELSE                          
   -(0)+(0)                        
  END                          
 end) as SALVAGE_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN -((PCCALC.SALVAGE)*PCCALC.SHARE/100+PCCALC.RSALVAGE) ELSE 0 END)                          
  ELSE                          
   -(0)                        
  END                          
 end) as SALVAGE_Settled, 

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  -(0)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   -(0)+(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.SUBROGATION)*PCCALC.SHARE/100+PCCALC.RSUBROGATION) ELSE 0 END)                          
  ELSE                          
   -(0)+(0)                        
  END                          
 end) as SUBROGATION_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN -((PCCALC.SUBROGATION)*PCCALC.SHARE/100+PCCALC.RSUBROGATION) ELSE 0 END)                          
  ELSE                          
   -(0)                        
  END                          
 end) as SUBROGATION_Settled, 
   
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (0)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (0)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.COST)*PCCALC.SHARE/100+PCCALC.RCOST) ELSE 0 END)                          
  ELSE                          
    (0)-(0)                        
  END                          
 end) as COST_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.COST)*PCCALC.SHARE/100+PCCALC.RCOST) ELSE 0 END)                          
  ELSE                          
   (0)                        
  END                          
 end) as COST_Settled,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (0)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (0)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.COST)*PCCALC.SHARE/100+PCCALC.RCOST)*(PCH.RETENTION + PCH.FRShare + PRH.SPRShare)/100 ELSE 0 END)                          
  ELSE                          
    (0)-(0)
  END                          
 end) as COST_OS_NET  
         
FROM CLAIM   
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO)   
LEFT JOIN Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
LEFT JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO)
LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=CLAIM.PCNO AND PCCALC.CURRENCY=CCALC.CURRENCY)                          
OUTER APPLY (SELECT TOP 1 TOR, CODE AS CODE FROM LCALC WHERE CNO=PCCALC.CNO Order By Case When LCALC.Currency=PCCALC.Currency Then 0 Else 1 End, Code, TOR) PLCALC
LEFT JOIN CARRHEADER  PCH ON (PCH.CNO=CLAIM.PCNO)  
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO)
LEFT JOIN RARRHEADER PRH ON (PRH.ANO=PCLAIM.ANO)
INNER JOIN fn_exchange(@P_EDate) as Currency On (Currency.Currency=CCalc.Currency)                 
WHERE                           
 CLAIM.REGDATE<=@P_EDATE AND (CLAIM.CTYPE<>'C' OR (CLAIM.CTYPE='C' AND CLAIM.CSTATUS in ('A','C') AND CLAIM.ADATE>@P_EDate) OR CLAIM.CSTATUS in ('P','T')) AND CLAIM.CSTATUS<>'R' AND          
 ((CLAIM.SETTLEDF=0 AND CLAIM.CSDATE<=@P_EDATE AND CLAIM.CSTATUS<>'C') OR                           
  (CLAIM.PSETTLEDF=0 AND CLAIM.CSDATE>@P_EDATE AND (CLAIM.PCSTATUS in ('P','A') or CLAIM.SETTLEDF=0 OR CLAIM.ADATE>@P_EDATE)))                                  


)                          
                                  
           

