DROP FUNCTION OS_CLAIM_BY_DETAIL_LOSS_EXPENSE

GO

CREATE FUNCTION OS_CLAIM_BY_DETAIL_LOSS_EXPENSE( @P_EDate as  smalldatetime)                        
RETURNS TABLE                         
AS RETURN (                        
SELECT                        
 CLAIM.OCNO, CLCOST.CCTYPE, CLCOST.ID AS PAYMENT, CLAIM.ANO, CLAIM.CNO, CLCOST.CURRENCY AS CURRENCY, CLCOST.RefNo, CLAIM.TOC, ACCEPTANCE.BRANCH,CURRENCY.RATE, CLAIM.ISTYPE, CLAIM.CLAIMNO,                  
  
 (CASE                        
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN          
  (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)
 ELSE                        
  CASE                         
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN          
   (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (PCLCOST.AMOUNT*(CASE WHEN PCLCOST.CONTRIBUTIONF=1 THEN PCCALC.SHARE ELSE (CASE WHEN PCLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100) ELSE 0 END)                        
  ELSE                        
   (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100)-(CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100)                      
  END                        
 end) as GROSS_OS,    

                          
 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100) AS GROSS_LOSS,    
                        
 (CASE                        
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN                        
  0                         
 ELSE                        
  CASE                         
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN                      
      
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN (PCLCOST.AMOUNT*(CASE WHEN PCLCOST.CONTRIBUTIONF=1 THEN PCCALC.SHARE ELSE (CASE WHEN PCLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100) ELSE 0 END)                        
  ELSE                        
   (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100)                      
  END                        
 end) as GROSS_SETTLED,

    
(CASE                        
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN          
  (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100)
 ELSE                        
  CASE                         
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN          
   (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (PCLCOST.AMOUNT*(CASE WHEN PCLCOST.CONTRIBUTIONF=0 AND PCLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) ELSE 0 END)                        
  ELSE                        
   (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100)-(CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100)                      
  END                        
 end) as EXPENSE_OS
           
FROM CLAIM 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
LEFT JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO)
LEFT JOIN Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
INNER JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) CLCOST ON (CLCOST.CNO=CCALC.CNO AND CLCOST.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) PCLCOST ON (PCLCOST.CNO=CLAIM.PCNO AND PCLCOST.ID=CLCOST.ID AND PCLCOST.Currency=CLCOST.Currency and PCLCOST.RefNo=CLCost.RefNo and PCLCost.CCType=CLCOST.CCTYPE)
LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=PCLCOST.CNO AND PCCALC.CURRENCY=PCLCOST.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN fn_exchange(@P_EDate) as Currency On (Currency.Currency=CCalc.Currency)            
WHERE                           
 CLAIM.REGDATE<=@P_EDATE AND (CLAIM.CTYPE<>'C' OR (CLAIM.CTYPE='C' AND CLAIM.CSTATUS in ('A','C') AND CLAIM.ADATE>@P_EDate) OR CLAIM.CSTATUS in ('P','T')) AND CLAIM.CSTATUS<>'R' AND          
 ((CLAIM.SETTLEDF=0 AND CLAIM.CSDATE<=@P_EDATE AND CLAIM.CSTATUS<>'C') OR                           
  (CLAIM.PSETTLEDF=0 AND CLAIM.CSDATE>@P_EDATE AND (CLAIM.PCSTATUS in ('P','A') or CLAIM.SETTLEDF=0 OR CLAIM.ADATE>@P_EDATE)))                                  
)                          
       

GO

DROP FUNCTION OS_CLAIM_BY_DETAIL_LOSS_PAYMENT

GO

CREATE FUNCTION OS_CLAIM_BY_DETAIL_LOSS_PAYMENT( @P_EDate as  smalldatetime)                        
RETURNS TABLE                         
AS RETURN (                        
SELECT                        
 CLAIM.OCNO, CLLOSS.PAYMENT, CLLOSS.REFNO, CLLOSS.TOI, CLLOSS.NOC, CLAIM.ANO, CLAIM.CNO, CLLOSS.CURRENCY, CLAIM.TOC, ACCEPTANCE.BRANCH,CURRENCY.RATE, CLAIM.ISTYPE, CLAIM.CLAIMNO,                  
  
 (CASE                        
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)
 ELSE                        
  CASE                         
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100) ELSE 0 END)
  ELSE                        
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)                      
  END                        
 end) as GROSS_OS,      

(CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EDAMOUNT/CH.ETAMOUNT ELSE 0 END)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EDAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(CASE WHEN PCH.TAMOUNT<>0 THEN PCH.DAMOUNT/PCH.TAMOUNT ELSE 0 END) ELSE 0 END)
  ELSE                          
    (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EDAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CASE WHEN CH.TAMOUNT<>0 THEN CH.DAMOUNT/CH.TAMOUNT ELSE 0 END)                        
  END                          
 end) as DECREE_OS,   

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.ECAMOUNT/CH.ETAMOUNT ELSE 0 END)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.ECAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(CASE WHEN PCH.TAMOUNT<>0 THEN PCH.CAMOUNT/PCH.TAMOUNT ELSE 0 END) ELSE 0 END)
  ELSE                          
    (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.ECAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CASE WHEN CH.TAMOUNT<>0 THEN CH.CAMOUNT/CH.TAMOUNT ELSE 0 END)                        
  END                          
 end) as BPPDAN_OS,   

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EXPAMOUNT/CH.ETAMOUNT ELSE 0 END)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EXPAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(CASE WHEN PCH.TAMOUNT<>0 THEN PCH.XPAMOUNT/PCH.TAMOUNT ELSE 0 END) ELSE 0 END)
  ELSE                          
    (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EXPAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CASE WHEN CH.TAMOUNT<>0 THEN CH.XPAMOUNT/CH.TAMOUNT ELSE 0 END)                        
  END                          
 end) as MAIPARK_OS,   

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EQAMOUNT/CH.ETAMOUNT ELSE 0 END)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EQAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(CASE WHEN PCH.TAMOUNT<>0 THEN PCH.QAMOUNT/PCH.TAMOUNT ELSE 0 END) ELSE 0 END)
  ELSE                          
    (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EQAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CASE WHEN CH.TAMOUNT<>0 THEN CH.QAMOUNT/CH.TAMOUNT ELSE 0 END)                        
  END                          
 end) as QUOTASHARE_OS,   

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN (CH.ESP1AMOUNT+CH.ESP2AMOUNT+CH.ESP3AMOUNT)/CH.ETAMOUNT ELSE 0 END)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN (CH.ESP1AMOUNT+CH.ESP2AMOUNT+CH.ESP3AMOUNT)/CH.ETAMOUNT ELSE 0 END)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(CASE WHEN PCH.TAMOUNT<>0 THEN (PCH.SP1AMOUNT+PCH.SP2AMOUNT+PCH.SP3AMOUNT)/PCH.TAMOUNT ELSE 0 END) ELSE 0 END)
  ELSE                          
    (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN (CH.ESP1AMOUNT+CH.ESP2AMOUNT+CH.ESP3AMOUNT)/CH.ETAMOUNT ELSE 0 END)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CASE WHEN CH.TAMOUNT<>0 THEN (CH.SP1AMOUNT+CH.SP2AMOUNT+CH.SP3AMOUNT)/CH.TAMOUNT ELSE 0 END)                        
  END                          
 end) as SURPLUS_OS,   
 
(CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EAAMOUNT/CH.ETAMOUNT ELSE 0 END)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EAAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(CASE WHEN PCH.TAMOUNT<>0 THEN PCH.AAMOUNT/PCH.TAMOUNT ELSE 0 END) ELSE 0 END)
  ELSE                          
    (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EAAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CASE WHEN CH.TAMOUNT<>0 THEN CH.AAMOUNT/CH.TAMOUNT ELSE 0 END)                        
  END                          
 end) as AUTOFAC_OS,  
   
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EFAMOUNT/CH.ETAMOUNT ELSE 0 END)
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EFAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(CASE WHEN PCH.TAMOUNT<>0 THEN PCH.FAMOUNT/PCH.TAMOUNT ELSE 0 END) ELSE 0 END)
  ELSE                          
    (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CASE WHEN CH.ETAMOUNT<>0 THEN CH.EFAMOUNT/CH.ETAMOUNT ELSE 0 END)-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CASE WHEN CH.TAMOUNT<>0 THEN CH.FAMOUNT/CH.TAMOUNT ELSE 0 END)                        
  END                          
 end) as FACULTATIVE_OS,   

 (CASE                        
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN                      
  (CLDED.CURRENT_ESTAMOUNT*CCALC.SHARE/100)
 ELSE                        
  CASE                         
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CLDED.CURRENT_ESTAMOUNT*CCALC.SHARE/100)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLDED.PREVIOUS_AMOUNT*PCCALC.SHARE/100) ELSE 0 END)
  ELSE                        
    (CLDED.CURRENT_ESTAMOUNT*CCALC.SHARE/100)-(CLDED.CURRENT_AMOUNT*CCALC.SHARE/100)                      
  END                        
 end) as DEDUCTIBLE_OS,      
 
 
(CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
 (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CH.ERETENTION + CH.EFRShare + RH.SPRShare)/100
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
  (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CH.ERETENTION + CH.EFRShare + RH.SPRShare)/100-(CASE WHEN PCCALC.CNO IS NOT NULL THEN (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)*(PCH.RETENTION + PCH.FRShare + PRH.SPRShare)/100 ELSE 0 END)                            

  ELSE                          
	(CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100)*(CH.ERETENTION + CH.EFRShare + RH.SPRShare)/100-(CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)*(CH.RETENTION + CH.FRShare + RH.SPRShare)/100                                         
  END                          
 end) as GROSS_OS_NET,   
                                    
 (CLLOSS.CURRENT_ESTIMATE*CCALC.SHARE/100) AS GROSS_LOSS,    

 (CLDED.CURRENT_ESTAMOUNT*CCALC.SHARE/100) AS GROSS_DEDUCTIBLE,    
                        
 (CASE                        
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE)  OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN                        
  0                         
 ELSE                        
  CASE                         
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN                      
      
   (CLLOSS.PREVIOUS_AMOUNT*PCCALC.SHARE/100)                        
  ELSE                        
   (CLLOSS.CURRENT_AMOUNT*CCALC.SHARE/100)                      
  END                        
 end) as GROSS_SETTLED,

 (CASE                        
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE)  OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN                        
  0                         
 ELSE                        
  CASE                         
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN                      
      
   (CLDED.PREVIOUS_AMOUNT*PCCALC.SHARE/100)                        
  ELSE                        
   (CLDED.CURRENT_AMOUNT*CCALC.SHARE/100)                      
  END                        
 end) as DEDUCTIBLE_SETTLED
      
FROM CLAIM 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
LEFT JOIN CARRHEADER CH ON (CH.CNO=CLAIM.CNO)  
LEFT JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO)
INNER JOIN RARRHEADER RH ON (RH.ANO=CLAIM.ANO)
LEFT JOIN RARRHEADER PRH ON (PRH.ANO=PCLAIM.ANO)
LEFT JOIN CARRHEADER PCH ON (PCH.CNO=CLAIM.PCNO)  
LEFT JOIN Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
Inner Join (

	SELECT CNO, PAYMENT, CURRENCY, REFNO, MAX(TOI) as TOI, MAX(NOC) as NOC, 
	sum(PREVIOUS_ESTIMATE) as PREVIOUS_ESTIMATE, 
	sum(PREVIOUS_AMOUNT) as PREVIOUS_AMOUNT, 
	sum(CURRENT_ESTIMATE) as CURRENT_ESTIMATE, 
	sum(CURRENT_AMOUNT) as CURRENT_AMOUNT
	From
	(
		SELECT CLAIM.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, 
		0 as PREVIOUS_ESTIMATE,
		0 as PREVIOUS_AMOUNT,
		SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as CURRENT_ESTIMATE, 
		SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as CURRENT_AMOUNT 
		FROM CLLOSS, CLAIM
		WHERE CLAIM.CNO=CLLOSS.CNO AND EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) 
		GROUP BY CLAIM.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO

		UNION ALL

		SELECT CLAIM.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, 
		SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as PREVIOUS_ESTIMATE, 
		SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as PREVIOUS_AMOUNT,
		0 as CURRENT_ESTIMATE,
		0 as CURRENT_AMOUNT
		FROM CLLOSS, CLAIM
		WHERE CLAIM.PCNO=CLLOSS.CNO AND EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) 
		GROUP BY CLAIM.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO
	) CLLOSS
	GROUP BY CNO, PAYMENT, CURRENCY, REFNO
) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY)   

Left JOIN (
	SELECT CNO, ID, REFNO, CURRENCY, 
	SUM(PREVIOUS_ESTAMOUNT) as PREVIOUS_ESTAMOUNT, 
	SUM(PREVIOUS_AMOUNT) AS PREVIOUS_AMOUNT, 
	sum(CURRENT_ESTAMOUNT) as CURRENT_ESTAMOUNT, 
	sum(CURRENT_AMOUNT) as CURRENT_AMOUNT
	FROM
	(
		SELECT CLAIM.CNO, CLDED.ID, CLDED.REFNO, CLDED.CURRENCY, 
		0 as PREVIOUS_ESTAMOUNT, 
		0 as PREVIOUS_AMOUNT, 
		SUM(CLDED.ESTAMOUNT) AS CURRENT_ESTAMOUNT, 
		SUM(CLDED.AMOUNT) AS CURRENT_AMOUNT 
		FROM CLDED, CLAIM
		WHERE CLAIM.CNO=CLDED.CNO
		AND EXISTS (SELECT TOP 1 DEDTAB.DCODE FROM LCALC, DEDTAB WHERE LCALC.CNO=CLAIM.CNO AND DEDTAB.DCODE=CLDED.DCODE AND DEDTAB.TOR=LCALC.TOR)
		GROUP BY CLAIM.CNO, CLDED.ID, CLDED.REFNO, CLDED.CURRENCY
		
		UNION ALL

		SELECT CLAIM.CNO, CLDED.ID, CLDED.REFNO, CLDED.CURRENCY, 
		SUM(CLDED.ESTAMOUNT) AS PREVIOUS_ESTAMOUNT, 
		SUM(CLDED.AMOUNT) AS PREVIOUS_AMOUNT, 
		0 as CURRENT_ESTAMOUNT, 
		0 as CURRENT_AMOUNT
		FROM CLDED, CLAIM
		WHERE CLAIM.PCNO=CLDED.CNO
		AND EXISTS (SELECT TOP 1 DEDTAB.DCODE FROM LCALC, DEDTAB WHERE LCALC.CNO=CLAIM.PCNO AND DEDTAB.DCODE=CLDED.DCODE AND DEDTAB.TOR=LCALC.TOR)
		GROUP BY CLAIM.CNO, CLDED.ID, CLDED.REFNO, CLDED.CURRENCY
	) CLDED
	GROUP BY CNO, ID, REFNO, CURRENCY
) 
CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.ID=CLLOSS.PAYMENT AND CLDED.REFNO=CLLOSS.REFNO)

LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=CLAIM.PCNO AND PCCALC.CURRENCY=CLLOSS.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN fn_exchange(@P_EDate) as Currency On (Currency.Currency=CCalc.Currency)            
WHERE                         
 CLAIM.REGDATE<=@P_EDATE AND (CLAIM.CTYPE<>'C' OR (CLAIM.CTYPE='C' AND CLAIM.CSTATUS in ('A','C') AND CLAIM.ADATE>@P_EDate) OR CLAIM.CSTATUS in ('P','T')) AND CLAIM.CSTATUS<>'R' AND          
 ((CLAIM.SETTLEDF=0 AND CLAIM.CSDATE<=@P_EDATE AND CLAIM.CSTATUS<>'C') OR                           
  (CLAIM.PSETTLEDF=0 AND CLAIM.CSDATE>@P_EDATE AND (CLAIM.PCSTATUS in ('P','A') or CLAIM.SETTLEDF=0 OR CLAIM.ADATE>@P_EDATE)))                                  

)                        

GO
DROP FUNCTION OS_CLAIM_BY_DETAIL

GO

CREATE FUNCTION OS_CLAIM_BY_DETAIL( @P_EDate as  smalldatetime)                          
RETURNS TABLE                           
AS RETURN (                          
SELECT                          
 CLAIM.OCNO, CLAIM.PAYMENT, CLAIM.ANO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, Currency.Rate, CLAIM.ISTYPE, CLAIM.CLAIMNO,                    
    
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)      
