  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    ((-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION))-CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSUBROGATION-PCCALC.SUBROGATION-PCCALC.RSUBROGATION)) ELSE 0 END)                          
  ELSE                          
    (-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION))-(-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION))                        
  END                          
 end) as OWNSUBROGATION_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    (CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSUBROGATION-PCCALC.SUBROGATION-PCCALC.RSUBROGATION)) ELSE 0 END)                          
  ELSE                          
    (-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION))                        
  END                          
 end) as OWNSUBROGATION_SETTLED,

  (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  (-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    ((-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))-CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSALVAGE-PCCALC.SALVAGE-PCCALC.RSALVAGE)) ELSE 0 END)                          
  ELSE                          
    (-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))-(-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE))                        
  END                          
 end) as OWNSALVAGE_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
    (CASE WHEN PCCALC.CNO IS NOT NULL THEN (-(PCCALC.TSALVAGE-PCCALC.SALVAGE-PCCALC.RSALVAGE)) ELSE 0 END)                          
  ELSE                          
    (-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE))                        
  END                          
 end) as OWNSALVAGE_SETTLED,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  ((CCALC.LOSS)*CCALC.SHARE/100)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   ((CCALC.LOSS)*CCALC.SHARE/100)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.CLAIM)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
    ((CCALC.LOSS)*CCALC.SHARE/100)-((CCALC.CLAIM)*CCALC.SHARE/100)                        
  END                          
 end) as LOSS_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.CLAIM)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
   ((CCALC.CLAIM)*CCALC.SHARE/100)                        
  END                          
 end) as LOSS_Settled, 
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  ((-CCALC.EDEDUCTIBLE)*CCALC.SHARE/100)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   ((-CCALC.EDEDUCTIBLE)*CCALC.SHARE/100)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((-PCCALC.DEDUCTIBLE)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
    ((-CCALC.EDEDUCTIBLE)*CCALC.SHARE/100)-((-CCALC.DEDUCTIBLE)*CCALC.SHARE/100)                        
  END                          
 end) as DEDUCTIBLE_OS,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((-PCCALC.DEDUCTIBLE)*PCCALC.SHARE/100) ELSE 0 END)                          
  ELSE                          
    ((-CCALC.DEDUCTIBLE)*CCALC.SHARE/100)                        
  END                          
 end) as DEDUCTIBLE_Settled,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  -((CCALC.ESALVAGE)*CCALC.SHARE/100+CCALC.ERSALVAGE)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   -((CCALC.ESALVAGE)*CCALC.SHARE/100+CCALC.ERSALVAGE)+(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.SALVAGE)*PCCALC.SHARE/100+PCCALC.RSALVAGE) ELSE 0 END)                          
  ELSE                          
   -((CCALC.ESALVAGE)*CCALC.SHARE/100+CCALC.ERSALVAGE)+((CCALC.SALVAGE)*CCALC.SHARE/100+CCALC.RSALVAGE)                        
  END                          
 end) as SALVAGE_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN -((PCCALC.SALVAGE)*PCCALC.SHARE/100+PCCALC.RSALVAGE) ELSE 0 END)                          
  ELSE                          
   -((CCALC.SALVAGE)*CCALC.SHARE/100+CCALC.RSALVAGE)                        
  END                          
 end) as SALVAGE_Settled, 
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  -((CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERSUBROGATION)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   -((CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERSUBROGATION)+(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.SUBROGATION)*PCCALC.SHARE/100+PCCALC.RSUBROGATION) ELSE 0 END)                          
  ELSE                          
   -((CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERSUBROGATION)+((CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RSUBROGATION)                        
  END                          
 end) as SUBROGATION_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN -((PCCALC.SUBROGATION)*PCCALC.SHARE/100+PCCALC.RSUBROGATION) ELSE 0 END)                          
  ELSE                          
   -((CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RSUBROGATION)                        
  END                          
 end) as SUBROGATION_Settled, 
   
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.COST)*PCCALC.SHARE/100+PCCALC.RCOST) ELSE 0 END)                          
  ELSE                          
    ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)-((CCALC.COST)*CCALC.SHARE/100+CCALC.RCOST)                        
  END                          
 end) as COST_OS,
 
 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)      
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)
  ELSE                          
    ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)
  END                          
 end) as COST_LOSS,

 (CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  0
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.COST)*PCCALC.SHARE/100+PCCALC.RCOST) ELSE 0 END)                          
  ELSE                          
   ((CCALC.COST)*CCALC.SHARE/100+CCALC.RCOST)                        
  END                          
 end) as COST_Settled,

(CASE                          
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN            
  ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)*(CH.ERETENTION + CH.EFRShare + RH.SPRShare)/100        
 ELSE                          
  CASE                           
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN            
   ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)*(CH.ERETENTION + CH.EFRShare + RH.SPRShare)/100 -(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.COST)*PCCALC.SHARE/100+PCCALC.RCOST)*(PCH.RETENTION + PCH.FRShare + PRH.SPRShare)/100 ELSE 0 END)                          
  ELSE                          
    ((CCALC.ECOST)*CCALC.SHARE/100+CCALC.ERCOST)*(CH.ERETENTION + CH.EFRShare + RH.SPRShare)/100 -((CCALC.COST)*CCALC.SHARE/100+CCALC.RCOST)*(CH.RETENTION + CH.FRShare + RH.SPRShare)/100
  END                          
 end) as COST_OS_NET
         
FROM CLAIM   
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO)   
INNER JOIN CARRHEADER CH ON (CH.CNO=CLAIM.CNO)  
LEFT JOIN Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
LEFT JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO)
LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=CLAIM.PCNO AND PCCALC.CURRENCY=CCALC.CURRENCY)                          
LEFT JOIN CARRHEADER  PCH ON (PCH.CNO=CLAIM.PCNO)  
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO)
INNER JOIN RARRHEADER RH ON (RH.ANO=CLAIM.ANO)
LEFT JOIN RARRHEADER PRH ON (PRH.ANO=PCLAIM.ANO)
INNER JOIN fn_exchange(@P_EDate) as Currency On (Currency.Currency=CCalc.Currency)                 
WHERE                           
 CLAIM.REGDATE<=@P_EDATE AND (CLAIM.CTYPE<>'C' OR (CLAIM.CTYPE='C' AND CLAIM.CSTATUS in ('A','C') AND CLAIM.ADATE>@P_EDate) OR CLAIM.CSTATUS in ('P','T')) AND CLAIM.CSTATUS<>'R' AND          
 ((CLAIM.SETTLEDF=0 AND CLAIM.CSDATE<=@P_EDATE AND CLAIM.CSTATUS<>'C') OR                           
  (CLAIM.PSETTLEDF=0 AND CLAIM.CSDATE>@P_EDATE AND (CLAIM.PCSTATUS in ('P','A') or CLAIM.SETTLEDF=0 OR CLAIM.ADATE>@P_EDATE)))                                  
)                          
                                  
            
    
GO



DROP FUNCTION OS_NET_CLAIM_BY_DETAIL

GO

CREATE FUNCTION OS_NET_CLAIM_BY_DETAIL( @P_EDate as  smalldatetime)                      
RETURNS TABLE                       
AS RETURN (                      
SELECT                      
 CLAIM.OCNO, CLAIM.PAYMENT, CLAIM.ANO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH,CURRENCY.RATE, CLAIM.ISTYPE, CLAIM.CLAIMNO,                
 (CASE                      
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN        
  ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))  
 ELSE                      
  CASE                       
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN        
   ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))-(CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.CLAIM-PCCALC.DEDUCTIBLE+PCCALC.COST-PCCALC.SALVAGE-PCCALC.SUBROGATION)*PCCALC.SHARE/100*(100-PCARRHEADER.MSHARE)/100+PCCALC.RCOST-PCCALC.RSUBROGATION-PCCALC.RSALVAGE+(PCCALC.TCOST-PCCALC.COST-PCCALC.RCOST)-(PCCALC.TSUBROGATION-PCCALC.SUBROGATION-PCCALC.RSUBROGATION)-(PCCALC.TSALVAGE-PCCALC.SALVAGE-PCCALC.RSALVAGE)) ELSE 0 END)                      
  ELSE                      
    ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))-((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE))                    
  END                      
 end) as GROSS_OS,                      
                      
 ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE)) AS GROSS_LOSS,  
                      
 (CASE                      
 When (CLAIM.CSEQNO=0 OR PCLAIM.CTYPE='C') AND ((CLAIM.CSTATUS IN ('P','T') AND CLAIM.CSDATE<=@P_EDATE) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE)  OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) ) THEN                      
  0                       
 ELSE                      
  CASE                       
  WHEN (CLAIM.CSTATUS in ('P','T')) OR (CLAIM.CSTATUS IN ('A') AND CLAIM.ADATE>@P_EDATE) OR (CLAIM.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND CLAIM.ADATE IS NOT NULL AND CLAIM.PCSTATUS<>'P' THEN CLAIM.ADATE ELSE CLAIM.CSDATE END)>@P_EDATE) THEN                      
  
   (CASE WHEN PCCALC.CNO IS NOT NULL THEN ((PCCALC.CLAIM-PCCALC.DEDUCTIBLE+PCCALC.COST-PCCALC.SALVAGE-PCCALC.SUBROGATION)*PCCALC.SHARE/100*(100-PCARRHEADER.MSHARE)/100+PCCALC.RCOST-PCCALC.RSUBROGATION-PCCALC.RSALVAGE+(PCCALC.TCOST-PCCALC.COST-PCCALC.RCOST)-(PCCALC.TSUBROGATION-PCCALC.SUBROGATION-PCCALC.RSUBROGATION)-(PCCALC.TSALVAGE-PCCALC.SALVAGE-PCCALC.RSALVAGE)) ELSE 0 END)                      
  ELSE                      
   ((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE))                    
  END                      
 end) as GROSS_SETTLED                      
                      
FROM CLAIM 
 INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
 Left Join Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
 LEFT JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO)
 LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=CLAIM.PCNO AND PCCALC.CURRENCY=CCALC.CURRENCY)                      
 INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) inner join fn_exchange(@P_EDate) as Currency On (Currency.Currency=CCalc.Currency)          
 INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)  
 LEFT  JOIN CARRHEADER PCARRHEADER ON (PCARRHEADER.CNO=CLAIM.PCNO)  
WHERE                       
 CLAIM.REGDATE<=@P_EDATE AND (CLAIM.CTYPE<>'C' OR (CLAIM.CTYPE='C' AND CLAIM.CSTATUS in ('A','C') AND CLAIM.ADATE>@P_EDate) OR CLAIM.CSTATUS in ('P','T')) AND CLAIM.CSTATUS<>'R' AND          
 ((CLAIM.SETTLEDF=0 AND CLAIM.CSDATE<=@P_EDATE AND CLAIM.CSTATUS<>'C') OR                       
  (CLAIM.PSETTLEDF=0 AND CLAIM.CSDATE>@P_EDATE AND (CLAIM.PCSTATUS in ('P','A') or CLAIM.SETTLEDF=0 OR CLAIM.ADATE>@P_EDATE)))                              
)                      
                          
  
GO      

DROP FUNCTION CLAIM_REGISTER_BY_DETAIL
GO
CREATE FUNCTION CLAIM_REGISTER_BY_DETAIL(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                        
RETURNS TABLE                         
AS RETURN (                                 
Select         
 Claim.RegDate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,                  
((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE)) AS CLAIM_REGISTER,        
(((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE)) AS CLAIM_REGISTER_NET    
from Claim INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
LEFT JOIN (SELECT CNO, CURRENCY, MAX(NOC) AS NOC, MAX(PAYMENT) AS PAYMENT FROM CLLOSS GROUP BY CNO, CURRENCY) CLLOSS ON (CLLOSS.CNO=CLAIM.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and Claim.CType<>'C' and Claim.CStatus<>'R' and Claim.PCStatus<>'R'        
        
UNION ALL        

Select         
 Claim.RegDate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY,PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                  
-((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE)) AS CLAIM_REGISTER,    
-(((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE)) AS CLAIM_REGISTER_NET    
from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
LEFT JOIN (SELECT CNO, CURRENCY, MAX(NOC) AS NOC, MAX(PAYMENT) AS PAYMENT FROM CLLOSS GROUP BY CNO, CURRENCY) CLLOSS ON (CLLOSS.CNO=PCLAIM.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0  and Claim.CType<>'C' and Claim.CStatus<>'R' and Claim.PCStatus<>'R'        
AND pClaim.CType<>'C' and not (PCLAIM.CStatus='C' AND PCLAIM.PCStatus='P')

UNION ALL

SELECT     
Claim.RegDate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY,PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                  
((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))     
- (CASE WHEN PCLAIM.SettledF=1 and PCLAIM.CStatus in ('C','A') and PCLAIM.PCStatus in ('','A') and PCLAIM.CType in ('N','E') Then ((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE)) else 0 end)  AS CLAIM_REGISTER,    

(((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))     
- (CASE WHEN PCLAIM.SettledF=1 and PCLAIM.CStatus in ('C','A') and PCLAIM.PCStatus in ('','A') and PCLAIM.CType in ('N','E') Then (((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE)) else 0 end)  AS CLAIM_REGISTER_NET        

from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
LEFT JOIN (SELECT CNO, CURRENCY, MAX(NOC) AS NOC, MAX(PAYMENT) AS PAYMENT FROM CLLOSS GROUP BY CNO, CURRENCY) CLLOSS ON (CLLOSS.CNO=PCLAIM.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0  and Claim.CType<>'C' and Claim.CStatus<>'R' and Claim.PCStatus<>'R'        
AND pClaim.CType<>'C' AND PCLAIM.CStatus='C' AND PCLAIM.PCStatus='A'
)        
          
      
GO

DROP FUNCTION CLAIM_SETTLE_BY_DETAIL

GO
CREATE FUNCTION CLAIM_SETTLE_BY_DETAIL(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                            
RETURNS TABLE                             
AS RETURN (                                     
SELECT            
 Claim.ADate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY, CCALC.RATE, CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,                      
(Case When Claim.CType<>'C' Then (CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) else 0 end) as CLAIM_SETTLE,      
(Case When Claim.CType<>'C' Then (CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE else 0 end) as GROSS_CLAIM_SETTLE,    
(Case When Claim.CType<>'C' Then ((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) else 0 end) as CLAIM_SETTLE_NET    
      
from Claim INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
LEFT JOIN (SELECT CNO, CURRENCY, MAX(NOC) AS NOC, MAX(PAYMENT) AS PAYMENT FROM CLLOSS GROUP BY CNO, CURRENCY) CLLOSS ON (CLLOSS.CNO=CLAIM.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)
Left Join Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
Where Claim.CStatus in ('C','A') and Claim.CType in ('N','E','C') and Claim.PCstatus in ('','A') and Claim.ADate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and NClaim.CSeqNo is null
            
UNION ALL            
            
SELECT            
  Claim.ADate as Date, PCLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY, CCALC.RATE, PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                      
-(Case When pClaim.CType<>'C' Then (CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) else 0 end) as CLAIM_SETTLE,      
-(Case When pClaim.CType<>'C' Then (CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE else 0 end) as GROSS_CLAIM_SETTLE,    
-(Case When pClaim.CType<>'C' Then ((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) else 0 end) as CLAIM_SETTLE_NET    
from Claim INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
LEFT JOIN (SELECT CNO, CURRENCY, MAX(NOC) AS NOC, MAX(PAYMENT) AS PAYMENT FROM CLLOSS GROUP BY CNO, CURRENCY) CLLOSS ON (CLLOSS.CNO=PCLAIM.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)
Where Claim.CStatus in ('C','A') and Claim.CType in ('N','E','C') and Claim.PCstatus in ('','A') and Claim.ADate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and pClaim.CSeqNo<Claim.CSeqNo
)                              
  
go
DROP  FUNCTION CLAIM_CLOSE_BY_DETAIL
GO
CREATE FUNCTION CLAIM_CLOSE_BY_DETAIL(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                    
RETURNS TABLE                     
AS RETURN (                             
SELECT     

Case When ((Claim.Cstatus='C' and Claim.PCStatus='R' and Claim.VSeqNo>1) or (Claim.Cstatus='C' and Claim.PCStatus='P') or (Claim.SettledF=1 and Claim.CStatus='C' and Claim.PCStatus='A')) and Claim.CSDate between @P_SDate and @P_EDate Then Claim.CSDate else Claim.ADate end as Date,
 CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,              
((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))     
- (CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then ((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE)) else 0 end)  AS CLAIM_CLOSE,    
(((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)+(CCALC.ETCOST-CCALC.ECOST-CCALC.ERCOST)-(CCALC.ETSUBROGATION-CCALC.ESUBROGATION-CCALC.ERSUBROGATION)-(CCALC.ETSALVAGE-CCALC.ESALVAGE-CCALC.ERSALVAGE))     
- (CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then (((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRShare/100)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE)) else 0 end)  AS CLAIM_CLOSE_NET        
from Claim INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
LEFT JOIN (SELECT CNO, CURRENCY, MAX(NOC) AS NOC, MAX(PAYMENT) AS PAYMENT FROM CLLOSS GROUP BY CNO, CURRENCY) CLLOSS ON (CLLOSS.CNO=CLAIM.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)    
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)
Where Claim.PSettledF=0 and    
(    
(Claim.CType='C' and Claim.CStatus not in ('R','P','T') and Claim.ADate Between @P_SDate and @P_EDate) Or    
(Claim.Cstatus='C' and Claim.PCStatus='R' and Claim.VSeqNo>1 and Claim.CSDate Between @P_SDate and @P_EDate) Or    
(Claim.Cstatus='C' and Claim.PCStatus='P' and Claim.CSDate Between @P_SDate and @P_EDate) Or    
(Claim.SettledF=1 and Claim.CStatus in ('C','A') and Claim.PCStatus='' and Claim.ADate Between @P_SDate and @P_EDate) or    
(Claim.SettledF=1 and Claim.CStatus='C' and Claim.PCStatus='A' and Claim.CSDate Between @P_SDate and @P_EDate)    
)    
)    
   
   

GO
DROP FUNCTION R_CLAIM_RESERVE
GO
CREATE FUNCTION R_CLAIM_RESERVE( @P_PEDATE as smalldatetime, @P_EDate as  smalldatetime)        
RETURNS TABLE         
AS RETURN (        
Select Branch, Currency, TOC,      
sum(PREVIOUS_LOSS_RESERVE) as PREVIOUS_LOSS_RESERVE, 
sum(PREVIOUS_EXPENSE_RESERVE) as PREVIOUS_EXPENSE_RESERVE, 
sum(PREVIOUS_SUBROGATION_RESERVE) as PREVIOUS_SUBROGATION_RESERVE, 
sum(PREVIOUS_SALVAGE_RESERVE) as PREVIOUS_SALVAGE_RESERVE, 
sum(PREVIOUS_COOUT_RESERVE) as PREVIOUS_COOUT_RESERVE, 
sum(PREVIOUS_GROSS_RESERVE) as PREVIOUS_GROSS_RESERVE, 

sum(PREVIOUS_BPPDAN_RESERVE) as PREVIOUS_BPPDAN_RESERVE, 
sum(PREVIOUS_MAIPARK_RESERVE) as PREVIOUS_MAIPARK_RESERVE, 
sum(PREVIOUS_DECREE_RESERVE) as PREVIOUS_DECREE_RESERVE, 
sum(PREVIOUS_QUOTASHARE_RESERVE) as PREVIOUS_QUOTASHARE_RESERVE, 
sum(PREVIOUS_QUOTASHARE_SHORTFALL_RESERVE) as PREVIOUS_QUOTASHARE_SHORTFALL_RESERVE, 
sum(PREVIOUS_SURPLUS_RESERVE) as PREVIOUS_SURPLUS_RESERVE, 
sum(PREVIOUS_SURPLUS_SHORTFALL_RESERVE) as PREVIOUS_SURPLUS_SHORTFALL_RESERVE, 
sum(PREVIOUS_AUTOFAC_RESERVE) as PREVIOUS_AUTOFAC_RESERVE, 
sum(PREVIOUS_FACULTATIVE_RESERVE) as PREVIOUS_FACULTATIVE_RESERVE, 
sum(PREVIOUS_FACULTATIVEQS_RESERVE) as PREVIOUS_FACULTATIVEQS_RESERVE, 
sum(PREVIOUS_FACULTATIVEAA_RESERVE) as PREVIOUS_FACULTATIVESP_RESERVE, 
sum(PREVIOUS_FACULTATIVEAA_RESERVE) as PREVIOUS_FACULTATIVEAA_RESERVE, 

sum(PREVIOUS_EXPENSE_BPPDAN_RESERVE) as PREVIOUS_EXPENSE_BPPDAN_RESERVE, 
sum(PREVIOUS_EXPENSE_MAIPARK_RESERVE) as PREVIOUS_EXPENSE_MAIPARK_RESERVE, 
sum(PREVIOUS_EXPENSE_DECREE_RESERVE) as PREVIOUS_EXPENSE_DECREE_RESERVE, 
sum(PREVIOUS_EXPENSE_QUOTASHARE_RESERVE) as PREVIOUS_EXPENSE_QUOTASHARE_RESERVE, 
sum(PREVIOUS_EXPENSE_SURPLUS_RESERVE) as PREVIOUS_EXPENSE_SURPLUS_RESERVE, 
sum(PREVIOUS_EXPENSE_AUTOFAC_RESERVE) as PREVIOUS_EXPENSE_AUTOFAC_RESERVE, 
sum(PREVIOUS_EXPENSE_FACULTATIVE_RESERVE) as PREVIOUS_EXPENSE_FACULTATIVE_RESERVE, 

sum(PREVIOUS_XOL_RESERVE) as PREVIOUS_XOL_RESERVE, 
sum(PREVIOUS_NET_RESERVE) as PREVIOUS_NET_RESERVE, 
sum(PREVIOUS_EXPENSE_NET_RESERVE) as PREVIOUS_EXPENSE_NET_RESERVE, 

sum(CURRENT_LOSS_RESERVE) as CURRENT_LOSS_RESERVE, 
sum(CURRENT_EXPENSE_RESERVE) as CURRENT_EXPENSE_RESERVE, 
sum(CURRENT_SUBROGATION_RESERVE) as CURRENT_SUBROGATION_RESERVE, 
sum(CURRENT_SALVAGE_RESERVE) as CURRENT_SALVAGE_RESERVE, 
sum(CURRENT_COOUT_RESERVE) as CURRENT_COOUT_RESERVE, 
sum(CURRENT_GROSS_RESERVE) as CURRENT_GROSS_RESERVE, 

sum(CURRENT_BPPDAN_RESERVE) as CURRENT_BPPDAN_RESERVE, 
sum(CURRENT_MAIPARK_RESERVE) as CURRENT_MAIPARK_RESERVE, 
sum(CURRENT_DECREE_RESERVE) as CURRENT_DECREE_RESERVE, 
sum(CURRENT_QUOTASHARE_RESERVE) as CURRENT_QUOTASHARE_RESERVE, 
sum(CURRENT_QUOTASHARE_SHORTFALL_RESERVE) as CURRENT_QUOTASHARE_SHORTFALL_RESERVE, 
sum(CURRENT_SURPLUS_RESERVE) as CURRENT_SURPLUS_RESERVE, 
sum(CURRENT_SURPLUS_SHORTFALL_RESERVE) as CURRENT_SURPLUS_SHORTFALL_RESERVE, 
sum(CURRENT_AUTOFAC_RESERVE) as CURRENT_AUTOFAC_RESERVE, 
sum(CURRENT_FACULTATIVE_RESERVE) as CURRENT_FACULTATIVE_RESERVE, 
sum(CURRENT_FACULTATIVEQS_RESERVE) as CURRENT_FACULTATIVEQS_RESERVE, 
sum(CURRENT_FACULTATIVESP_RESERVE) as CURRENT_FACULTATIVESP_RESERVE, 
sum(CURRENT_FACULTATIVEAA_RESERVE) as CURRENT_FACULTATIVEAA_RESERVE, 

sum(CURRENT_EXPENSE_BPPDAN_RESERVE) as CURRENT_EXPENSE_BPPDAN_RESERVE, 
sum(CURRENT_EXPENSE_MAIPARK_RESERVE) as CURRENT_EXPENSE_MAIPARK_RESERVE, 
sum(CURRENT_EXPENSE_DECREE_RESERVE) as CURRENT_EXPENSE_DECREE_RESERVE, 
sum(CURRENT_EXPENSE_QUOTASHARE_RESERVE) as CURRENT_EXPENSE_QUOTASHARE_RESERVE, 
sum(CURRENT_EXPENSE_SURPLUS_RESERVE) as CURRENT_EXPENSE_SURPLUS_RESERVE, 
sum(CURRENT_EXPENSE_AUTOFAC_RESERVE) as CURRENT_EXPENSE_AUTOFAC_RESERVE, 
sum(CURRENT_EXPENSE_FACULTATIVE_RESERVE) as CURRENT_EXPENSE_FACULTATIVE_RESERVE, 

sum(CURRENT_XOL_RESERVE) as CURRENT_XOL_RESERVE, 
sum(CURRENT_NET_RESERVE) as CURRENT_NET_RESERVE,
sum(CURRENT_EXPENSE_NET_RESERVE) as CURRENT_EXPENSE_NET_RESERVE
From (      
       select O.CNO, O.Branch, SysTab.CURRENCY, O.TOC,       
       cast (0 as Float) as PREVIOUS_LOSS_RESERVE, 
       cast (0 as Float) as PREVIOUS_DEDUCTIBLE_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_RESERVE, 
       cast (0 as Float) as PREVIOUS_SUBROGATION_RESERVE, 
       cast (0 as Float) as PREVIOUS_SALVAGE_RESERVE, 
       cast (0 as Float) as PREVIOUS_COOUT_RESERVE, 
       cast (0 as Float) as PREVIOUS_GROSS_RESERVE, 

       cast (0 as Float) as PREVIOUS_BPPDAN_RESERVE, 
       cast (0 as Float) as PREVIOUS_MAIPARK_RESERVE, 
       cast (0 as Float) as PREVIOUS_DECREE_RESERVE, 
       cast (0 as Float) as PREVIOUS_QUOTASHARE_RESERVE, 
	   cast (0 as Float) as PREVIOUS_QUOTASHARE_SHORTFALL_RESERVE,
       cast (0 as Float) as PREVIOUS_SURPLUS_RESERVE, 
	   cast (0 as Float) as PREVIOUS_SURPLUS_SHORTFALL_RESERVE, 
       cast (0 as Float) as PREVIOUS_AUTOFAC_RESERVE, 
       cast (0 as Float) as PREVIOUS_FACULTATIVE_RESERVE, 
	   cast (0 as Float) as PREVIOUS_FACULTATIVEQS_RESERVE, 
	   cast (0 as Float) as PREVIOUS_FACULTATIVESP_RESERVE, 
	   cast (0 as Float) as PREVIOUS_FACULTATIVEAA_RESERVE, 

       cast (0 as Float) as PREVIOUS_EXPENSE_BPPDAN_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_MAIPARK_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_DECREE_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_QUOTASHARE_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_SURPLUS_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_AUTOFAC_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_FACULTATIVE_RESERVE, 

       cast (0 as Float) as PREVIOUS_XOL_RESERVE, 
       cast (0 as Float) as PREVIOUS_NET_RESERVE, 
	   cast (0 as Float) as PREVIOUS_EXPENSE_NET_RESERVE, 

       ((O.LOSS_OS)*O.RATE) as CURRENT_LOSS_RESERVE,
       ((O.DEDUCTIBLE_OS)*O.RATE) as CURRENT_DEDUCTIBLE_RESERVE,
       ((O.COST_OS+O.EXPENSE_OS)*O.RATE) as CURRENT_EXPENSE_RESERVE,
       ((O.SUBROGATION_OS+O.OWNSUBROGATION_OS)*O.RATE) as CURRENT_SUBROGATION_RESERVE,
       ((O.SALVAGE_OS+O.OWNSALVAGE_OS)*O.RATE) as CURRENT_SALVAGE_RESERVE,
       (-(O.GROSS_OS*C.MSHARE/100)*O.RATE) AS CURRENT_COOUT_RESERVE,
       ((O.GROSS_OS*(100-C.MShare)/100+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS CURRENT_GROSS_RESERVE, 

       (-(O.BPPDAN_OS)*O.RATE) as CURRENT_BPPDAN_RESERVE,
       (-(O.MAIPARK_OS)*O.RATE) as CURRENT_MAIPARK_RESERVE,
       (-(O.DECREE_OS)*O.RATE) as CURRENT_DECREE_RESERVE,
       (-(O.QUOTASHARE_OS)*O.RATE) as CURRENT_QUOTASHARE_RESERVE,
	   ((O.QUOTASHARESF_OS)*O.RATE) as CURRENT_QUOTASHARE_SHORTFALL_RESERVE,
       (-(O.SURPLUS_OS)*O.RATE) as CURRENT_SURPLUS_RESERVE,
	   ((O.SURPLUSSF_OS)*O.RATE) as CURRENT_SURPLUS_SHORTFALL_RESERVE,
       (-(O.AUTOFAC_OS)*O.RATE)as CURRENT_AUTOFAC_RESERVE,
       (-(O.FACULTATIVE_OS)*O.RATE) as CURRENT_FACULTATIVE_RESERVE,
	   (-(O.FACULTATIVEQS_OS)*O.RATE) as CURRENT_FACULTATIVEQS_RESERVE,
	   (-(O.FACULTATIVESP_OS)*O.RATE) as CURRENT_FACULTATIVESP_RESERVE,
	   (-(O.FACULTATIVEAA_OS)*O.RATE) as CURRENT_FACULTATIVEAA_RESERVE,

	   (-(O.EXPENSE_BPPDAN_OS)*O.RATE) as CURRENT_EXPENSE_BPPDAN_RESERVE,
       (-(O.EXPENSE_MAIPARK_OS)*O.RATE) as CURRENT_EXPENSE_MAIPARK_RESERVE,
       (-(O.EXPENSE_DECREE_OS)*O.RATE) as CURRENT_EXPENSE_DECREE_RESERVE,
       (-(O.EXPENSE_QUOTASHARE_OS)*O.RATE) as CURRENT_EXPENSE_QUOTASHARE_RESERVE,
       (-(O.EXPENSE_SURPLUS_OS)*O.RATE) as CURRENT_EXPENSE_SURPLUS_RESERVE,
       (-(O.EXPENSE_AUTOFAC_OS)*O.RATE)as CURRENT_EXPENSE_AUTOFAC_RESERVE,
       (-(O.EXPENSE_FACULTATIVE_OS)*O.RATE) as CURRENT_EXPENSE_FACULTATIVE_RESERVE,

       (-(O.GROSS_OS_XOL)*O.RATE) as CURRENT_XOL_RESERVE,
       ((O.GROSS_OS_NET+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS CURRENT_NET_RESERVE,
	   ((O.COST_OS_NET+O.EXPENSE_OS)*O.Rate) AS CURRENT_EXPENSE_NET_RESERVE
       from OS_CLAIM_BY_DETAIL(@P_EDATE) O
	   Inner Join CArrHeader C on (C.CNO=O.CNO)
	   Inner join SysTab on (1=1)      

       union all        

       select O.CNO, O.Branch, SysTab.CURRENCY, O.TOC,       
       ((O.LOSS_OS)*O.RATE) as PREVIOUS_LOSS_RESERVE,
       ((O.DEDUCTIBLE_OS)*O.RATE) as PREVIOUS_DEDUCTIBLE_RESERVE,
       ((O.COST_OS+O.EXPENSE_OS)*O.RATE) as PREVIOUS_EXPENSE_RESERVE,
       ((O.SUBROGATION_OS+O.OWNSUBROGATION_OS)*O.RATE) as PREVIOUS_SUBROGATION_RESERVE,
       ((O.SALVAGE_OS+O.OWNSALVAGE_OS)*O.RATE) as PREVIOUS_SALVAGE_RESERVE,
       (-(O.GROSS_OS*C.MSHARE/100)*O.RATE) AS PREVIOUS_COOUT_RESERVE,
       ((O.GROSS_OS*(100-C.MShare)/100+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS PREVIOUS_GROSS_RESERVE, 

       (-(O.BPPDAN_OS)*O.RATE) as PREVIOUS_BPPDAN_RESERVE,
       (-(O.MAIPARK_OS)*O.RATE) as PREVIOUS_MAIPARK_RESERVE,
       (-(O.DECREE_OS)*O.RATE) as PREVIOUS_DECREE_RESERVE,
       (-(O.QUOTASHARE_OS)*O.RATE) as PREVIOUS_QUOTASHARE_RESERVE,
	   ((O.QUOTASHARESF_OS)*O.RATE) as PREVIOUS_QUOTASHARE_SHORTFALL_RESERVE,
       (-(O.SURPLUS_OS)*O.RATE) as PREVIOUS_SURPLUS_RESERVE,
	   ((O.SURPLUSSF_OS)*O.RATE) as PREVIOUS_SURPLUS_SHORTFALL_RESERVE,
       (-(O.AUTOFAC_OS)*O.RATE)as PREVIOUS_AUTOFAC_RESERVE,
       (-(O.FACULTATIVE_OS)*O.RATE) as PREVIOUS_FACULTATIVE_RESERVE,
	   (-(O.FACULTATIVEQS_OS)*O.RATE) as PREVIOUS_FACULTATIVEQS_RESERVE,
	   (-(O.FACULTATIVESP_OS)*O.RATE) as PREVIOUS_FACULTATIVESP_RESERVE,
	   (-(O.FACULTATIVEAA_OS)*O.RATE) as PREVIOUS_FACULTATIVEAA_RESERVE,

	   (-(O.EXPENSE_BPPDAN_OS)*O.RATE) as PREVIOUS_EXPENSE_BPPDAN_RESERVE,
       (-(O.EXPENSE_MAIPARK_OS)*O.RATE) as PREVIOUS_EXPENSE_MAIPARK_RESERVE,
       (-(O.EXPENSE_DECREE_OS)*O.RATE) as PREVIOUS_EXPENSE_DECREE_RESERVE,
       (-(O.EXPENSE_QUOTASHARE_OS)*O.RATE) as PREVIOUS_EXPENSE_QUOTASHARE_RESERVE,
       (-(O.EXPENSE_SURPLUS_OS)*O.RATE) as PREVIOUS_EXPENSE_SURPLUS_RESERVE,
       (-(O.EXPENSE_AUTOFAC_OS)*O.RATE)as PREVIOUS_EXPENSE_AUTOFAC_RESERVE,
       (-(O.EXPENSE_FACULTATIVE_OS)*O.RATE) as PREVIOUS_EXPENSE_FACULTATIVE_RESERVE,

       (-(O.GROSS_OS_XOL)*O.RATE) as PREVIOUS_XOL_RESERVE,
       ((O.GROSS_OS_NET+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS PREVIOUS_NET_RESERVE,
	   ((O.COST_OS_NET+O.EXPENSE_OS)*O.Rate) AS PREVIOUS_EXPENSE_NET_RESERVE,

       cast (0 as Float) as CURRENT_LOSS_RESERVE, 
       cast (0 as Float) as CURRENT_DEDUCTIBLE_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_RESERVE, 
       cast (0 as Float) as CURRENT_SUBROGATION_RESERVE, 
       cast (0 as Float) as CURRENT_SALVAGE_RESERVE, 
       cast (0 as Float) as CURRENT_COOUT_RESERVE, 
       cast (0 as Float) as CURRENT_GROSS_RESERVE, 

       cast (0 as Float) as CURRENT_BPPDAN_RESERVE, 
       cast (0 as Float) as CURRENT_MAIPARK_RESERVE, 
       cast (0 as Float) as CURRENT_DECREE_RESERVE, 
       cast (0 as Float) as CURRENT_QUOTASHARE_RESERVE, 
	   cast (0 as Float) as CURRENT_QUOTASHARE_SHORTFALL_RESERVE,
       cast (0 as Float) as CURRENT_SURPLUS_RESERVE, 
	   cast (0 as Float) as CURRENT_SURPLUS_SHORTFALL_RESERVE, 
       cast (0 as Float) as CURRENT_AUTOFAC_RESERVE, 
       cast (0 as Float) as CURRENT_FACULTATIVE_RESERVE, 
	   cast (0 as Float) as CURRENT_FACULTATIVEQS_RESERVE, 
	   cast (0 as Float) as CURRENT_FACULTATIVESP_RESERVE, 
	   cast (0 as Float) as CURRENT_FACULTATIVEAA_RESERVE, 

       cast (0 as Float) as CURRENT_EXPENSE_BPPDAN_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_MAIPARK_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_DECREE_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_QUOTASHARE_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_SURPLUS_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_AUTOFAC_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_FACULTATIVE_RESERVE, 

       cast (0 as Float) as CURRENT_XOL_RESERVE, 
       cast (0 as Float) as CURRENT_NET_RESERVE,
	   cast (0 as Float) as CURRENT_EXPENSE_NET_RESERVE

       from OS_CLAIM_BY_DETAIL(@P_PEDATE) O
	   Inner Join CArrHeader C on (C.CNO=O.CNO)
	   Inner join SysTab on (1=1)
) O      
Group By Branch, Currency, TOC      

)        
          


          
