CREATE FUNCTION R_CLAIM_RESERVE_DETAIL( @P_PEDATE as smalldatetime, @P_EDate as  smalldatetime)        
RETURNS TABLE         
AS RETURN (        
Select CNO, Branch, Currency, TOC,      
sum(PREVIOUS_LOSS_RESERVE) as PREVIOUS_LOSS_RESERVE, 
