sum(PREVIOUS_SURPLUS_RESERVE) as PREVIOUS_SURPLUS_RESERVE, 
sum(PREVIOUS_SURPLUS_SHORTFALL_RESERVE) as PREVIOUS_SURPLUS_SHORTFALL_RESERVE, 
sum(PREVIOUS_AUTOFAC_RESERVE) as PREVIOUS_AUTOFAC_RESERVE, 
sum(PREVIOUS_FACULTATIVE_RESERVE) as PREVIOUS_FACULTATIVE_RESERVE, 
sum(PREVIOUS_FACULTATIVEQS_RESERVE) as PREVIOUS_FACULTATIVEQS_RESERVE, 
sum(PREVIOUS_FACULTATIVEAA_RESERVE) as PREVIOUS_FACULTATIVESP_RESERVE, 
