sum(PREVIOUS_EXPENSE_AUTOFAC_RESERVE) as PREVIOUS_EXPENSE_AUTOFAC_RESERVE, 
sum(PREVIOUS_EXPENSE_FACULTATIVE_RESERVE) as PREVIOUS_EXPENSE_FACULTATIVE_RESERVE, 

sum(PREVIOUS_XOL_RESERVE) as PREVIOUS_XOL_RESERVE, 
sum(PREVIOUS_NET_RESERVE) as PREVIOUS_NET_RESERVE, 
sum(PREVIOUS_EXPENSE_NET_RESERVE) as PREVIOUS_EXPENSE_NET_RESERVE, 

sum(CURRENT_LOSS_RESERVE) as CURRENT_LOSS_RESERVE, 
sum(CURRENT_EXPENSE_RESERVE) as CURRENT_EXPENSE_RESERVE, 
sum(CURRENT_SUBROGATION_RESERVE) as CURRENT_SUBROGATION_RESERVE, 
sum(CURRENT_SALVAGE_RESERVE) as CURRENT_SALVAGE_RESERVE, 
sum(CURRENT_COOUT_RESERVE) as CURRENT_COOUT_RESERVE, 
sum(CURRENT_GROSS_RESERVE) as CURRENT_GROSS_RESERVE, 

sum(CURRENT_BPPDAN_RESERVE) as CURRENT_BPPDAN_RESERVE, 
sum(CURRENT_MAIPARK_RESERVE) as CURRENT_MAIPARK_RESERVE, 
sum(CURRENT_DECREE_RESERVE) as CURRENT_DECREE_RESERVE, 
sum(CURRENT_QUOTASHARE_RESERVE) as CURRENT_QUOTASHARE_RESERVE, 
sum(CURRENT_QUOTASHARE_SHORTFALL_RESERVE) as CURRENT_QUOTASHARE_SHORTFALL_RESERVE, 
sum(CURRENT_SURPLUS_RESERVE) as CURRENT_SURPLUS_RESERVE, 
sum(CURRENT_SURPLUS_SHORTFALL_RESERVE) as CURRENT_SURPLUS_SHORTFALL_RESERVE, 
sum(CURRENT_AUTOFAC_RESERVE) as CURRENT_AUTOFAC_RESERVE, 
sum(CURRENT_FACULTATIVE_RESERVE) as CURRENT_FACULTATIVE_RESERVE, 
sum(CURRENT_FACULTATIVEQS_RESERVE) as CURRENT_FACULTATIVEQS_RESERVE, 
sum(CURRENT_FACULTATIVESP_RESERVE) as CURRENT_FACULTATIVESP_RESERVE, 
sum(CURRENT_FACULTATIVEAA_RESERVE) as CURRENT_FACULTATIVEAA_RESERVE, 

sum(CURRENT_EXPENSE_BPPDAN_RESERVE) as CURRENT_EXPENSE_BPPDAN_RESERVE, 
sum(CURRENT_EXPENSE_MAIPARK_RESERVE) as CURRENT_EXPENSE_MAIPARK_RESERVE, 
sum(CURRENT_EXPENSE_DECREE_RESERVE) as CURRENT_EXPENSE_DECREE_RESERVE, 
sum(CURRENT_EXPENSE_QUOTASHARE_RESERVE) as CURRENT_EXPENSE_QUOTASHARE_RESERVE, 
sum(CURRENT_EXPENSE_SURPLUS_RESERVE) as CURRENT_EXPENSE_SURPLUS_RESERVE, 
sum(CURRENT_EXPENSE_AUTOFAC_RESERVE) as CURRENT_EXPENSE_AUTOFAC_RESERVE, 
sum(CURRENT_EXPENSE_FACULTATIVE_RESERVE) as CURRENT_EXPENSE_FACULTATIVE_RESERVE, 

sum(CURRENT_XOL_RESERVE) as CURRENT_XOL_RESERVE, 
sum(CURRENT_NET_RESERVE) as CURRENT_NET_RESERVE,
sum(CURRENT_EXPENSE_NET_RESERVE) as CURRENT_EXPENSE_NET_RESERVE
From (      
       select O.CNO, O.Branch, SysTab.CURRENCY, O.TOC,       
       cast (0 as Float) as PREVIOUS_LOSS_RESERVE, 
       cast (0 as Float) as PREVIOUS_DEDUCTIBLE_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_RESERVE, 
       cast (0 as Float) as PREVIOUS_SUBROGATION_RESERVE, 
       cast (0 as Float) as PREVIOUS_SALVAGE_RESERVE, 
       cast (0 as Float) as PREVIOUS_COOUT_RESERVE, 
       cast (0 as Float) as PREVIOUS_GROSS_RESERVE, 

       cast (0 as Float) as PREVIOUS_BPPDAN_RESERVE, 
       cast (0 as Float) as PREVIOUS_MAIPARK_RESERVE, 
       cast (0 as Float) as PREVIOUS_DECREE_RESERVE, 
       cast (0 as Float) as PREVIOUS_QUOTASHARE_RESERVE, 
	   cast (0 as Float) as PREVIOUS_QUOTASHARE_SHORTFALL_RESERVE,
       cast (0 as Float) as PREVIOUS_SURPLUS_RESERVE, 
	   cast (0 as Float) as PREVIOUS_SURPLUS_SHORTFALL_RESERVE, 
       cast (0 as Float) as PREVIOUS_AUTOFAC_RESERVE, 
       cast (0 as Float) as PREVIOUS_FACULTATIVE_RESERVE, 
	   cast (0 as Float) as PREVIOUS_FACULTATIVEQS_RESERVE, 
	   cast (0 as Float) as PREVIOUS_FACULTATIVESP_RESERVE, 
	   cast (0 as Float) as PREVIOUS_FACULTATIVEAA_RESERVE, 

       cast (0 as Float) as PREVIOUS_EXPENSE_BPPDAN_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_MAIPARK_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_DECREE_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_QUOTASHARE_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_SURPLUS_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_AUTOFAC_RESERVE, 
       cast (0 as Float) as PREVIOUS_EXPENSE_FACULTATIVE_RESERVE, 

       cast (0 as Float) as PREVIOUS_XOL_RESERVE, 
       cast (0 as Float) as PREVIOUS_NET_RESERVE, 
	   cast (0 as Float) as PREVIOUS_EXPENSE_NET_RESERVE, 

       ((O.LOSS_OS)*O.RATE) as CURRENT_LOSS_RESERVE,
       ((O.DEDUCTIBLE_OS)*O.RATE) as CURRENT_DEDUCTIBLE_RESERVE,
       ((O.COST_OS+O.EXPENSE_OS)*O.RATE) as CURRENT_EXPENSE_RESERVE,
       ((O.SUBROGATION_OS+O.OWNSUBROGATION_OS)*O.RATE) as CURRENT_SUBROGATION_RESERVE,
       ((O.SALVAGE_OS+O.OWNSALVAGE_OS)*O.RATE) as CURRENT_SALVAGE_RESERVE,
       (-(O.GROSS_OS*C.MSHARE/100)*O.RATE) AS CURRENT_COOUT_RESERVE,
       ((O.GROSS_OS*(100-C.MShare)/100+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS CURRENT_GROSS_RESERVE, 

       (-(O.BPPDAN_OS)*O.RATE) as CURRENT_BPPDAN_RESERVE,
       (-(O.MAIPARK_OS)*O.RATE) as CURRENT_MAIPARK_RESERVE,
       (-(O.DECREE_OS)*O.RATE) as CURRENT_DECREE_RESERVE,
       (-(O.QUOTASHARE_OS)*O.RATE) as CURRENT_QUOTASHARE_RESERVE,
	   ((O.QUOTASHARESF_OS)*O.RATE) as CURRENT_QUOTASHARE_SHORTFALL_RESERVE,
       (-(O.SURPLUS_OS)*O.RATE) as CURRENT_SURPLUS_RESERVE,
	   ((O.SURPLUSSF_OS)*O.RATE) as CURRENT_SURPLUS_SHORTFALL_RESERVE,
       (-(O.AUTOFAC_OS)*O.RATE)as CURRENT_AUTOFAC_RESERVE,
       (-(O.FACULTATIVE_OS)*O.RATE) as CURRENT_FACULTATIVE_RESERVE,
	   (-(O.FACULTATIVEQS_OS)*O.RATE) as CURRENT_FACULTATIVEQS_RESERVE,
	   (-(O.FACULTATIVESP_OS)*O.RATE) as CURRENT_FACULTATIVESP_RESERVE,
	   (-(O.FACULTATIVEAA_OS)*O.RATE) as CURRENT_FACULTATIVEAA_RESERVE,

	   (-(O.EXPENSE_BPPDAN_OS)*O.RATE) as CURRENT_EXPENSE_BPPDAN_RESERVE,
       (-(O.EXPENSE_MAIPARK_OS)*O.RATE) as CURRENT_EXPENSE_MAIPARK_RESERVE,
       (-(O.EXPENSE_DECREE_OS)*O.RATE) as CURRENT_EXPENSE_DECREE_RESERVE,
       (-(O.EXPENSE_QUOTASHARE_OS)*O.RATE) as CURRENT_EXPENSE_QUOTASHARE_RESERVE,
       (-(O.EXPENSE_SURPLUS_OS)*O.RATE) as CURRENT_EXPENSE_SURPLUS_RESERVE,
       (-(O.EXPENSE_AUTOFAC_OS)*O.RATE)as CURRENT_EXPENSE_AUTOFAC_RESERVE,
       (-(O.EXPENSE_FACULTATIVE_OS)*O.RATE) as CURRENT_EXPENSE_FACULTATIVE_RESERVE,

       (-(O.GROSS_OS_XOL)*O.RATE) as CURRENT_XOL_RESERVE,
       ((O.GROSS_OS_NET+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS CURRENT_NET_RESERVE,
	   ((O.COST_OS_NET+O.EXPENSE_OS)*O.Rate) AS CURRENT_EXPENSE_NET_RESERVE
       from OS_CLAIM_BY_DETAIL(@P_EDATE) O
	   Inner Join CArrHeader C on (C.CNO=O.CNO)
	   Inner join SysTab on (1=1)      

       union all        

       select O.CNO, O.Branch, SysTab.CURRENCY, O.TOC,       
       ((O.LOSS_OS)*O.RATE) as PREVIOUS_LOSS_RESERVE,
       ((O.DEDUCTIBLE_OS)*O.RATE) as PREVIOUS_DEDUCTIBLE_RESERVE,
       ((O.COST_OS+O.EXPENSE_OS)*O.RATE) as PREVIOUS_EXPENSE_RESERVE,
       ((O.SUBROGATION_OS+O.OWNSUBROGATION_OS)*O.RATE) as PREVIOUS_SUBROGATION_RESERVE,
       ((O.SALVAGE_OS+O.OWNSALVAGE_OS)*O.RATE) as PREVIOUS_SALVAGE_RESERVE,
       (-(O.GROSS_OS*C.MSHARE/100)*O.RATE) AS PREVIOUS_COOUT_RESERVE,
       ((O.GROSS_OS*(100-C.MShare)/100+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS PREVIOUS_GROSS_RESERVE, 

       (-(O.BPPDAN_OS)*O.RATE) as PREVIOUS_BPPDAN_RESERVE,
       (-(O.MAIPARK_OS)*O.RATE) as PREVIOUS_MAIPARK_RESERVE,
       (-(O.DECREE_OS)*O.RATE) as PREVIOUS_DECREE_RESERVE,
       (-(O.QUOTASHARE_OS)*O.RATE) as PREVIOUS_QUOTASHARE_RESERVE,
	   ((O.QUOTASHARESF_OS)*O.RATE) as PREVIOUS_QUOTASHARE_SHORTFALL_RESERVE,
       (-(O.SURPLUS_OS)*O.RATE) as PREVIOUS_SURPLUS_RESERVE,
	   ((O.SURPLUSSF_OS)*O.RATE) as PREVIOUS_SURPLUS_SHORTFALL_RESERVE,
       (-(O.AUTOFAC_OS)*O.RATE)as PREVIOUS_AUTOFAC_RESERVE,
       (-(O.FACULTATIVE_OS)*O.RATE) as PREVIOUS_FACULTATIVE_RESERVE,
	   (-(O.FACULTATIVEQS_OS)*O.RATE) as PREVIOUS_FACULTATIVEQS_RESERVE,
	   (-(O.FACULTATIVESP_OS)*O.RATE) as PREVIOUS_FACULTATIVESP_RESERVE,
	   (-(O.FACULTATIVEAA_OS)*O.RATE) as PREVIOUS_FACULTATIVEAA_RESERVE,

	   (-(O.EXPENSE_BPPDAN_OS)*O.RATE) as PREVIOUS_EXPENSE_BPPDAN_RESERVE,
       (-(O.EXPENSE_MAIPARK_OS)*O.RATE) as PREVIOUS_EXPENSE_MAIPARK_RESERVE,
       (-(O.EXPENSE_DECREE_OS)*O.RATE) as PREVIOUS_EXPENSE_DECREE_RESERVE,
       (-(O.EXPENSE_QUOTASHARE_OS)*O.RATE) as PREVIOUS_EXPENSE_QUOTASHARE_RESERVE,
       (-(O.EXPENSE_SURPLUS_OS)*O.RATE) as PREVIOUS_EXPENSE_SURPLUS_RESERVE,
       (-(O.EXPENSE_AUTOFAC_OS)*O.RATE)as PREVIOUS_EXPENSE_AUTOFAC_RESERVE,
       (-(O.EXPENSE_FACULTATIVE_OS)*O.RATE) as PREVIOUS_EXPENSE_FACULTATIVE_RESERVE,

       (-(O.GROSS_OS_XOL)*O.RATE) as PREVIOUS_XOL_RESERVE,
       ((O.GROSS_OS_NET+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS)*O.Rate) AS PREVIOUS_NET_RESERVE,
	   ((O.COST_OS_NET+O.EXPENSE_OS)*O.Rate) AS PREVIOUS_EXPENSE_NET_RESERVE,

       cast (0 as Float) as CURRENT_LOSS_RESERVE, 
       cast (0 as Float) as CURRENT_DEDUCTIBLE_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_RESERVE, 
       cast (0 as Float) as CURRENT_SUBROGATION_RESERVE, 
       cast (0 as Float) as CURRENT_SALVAGE_RESERVE, 
       cast (0 as Float) as CURRENT_COOUT_RESERVE, 
       cast (0 as Float) as CURRENT_GROSS_RESERVE, 

       cast (0 as Float) as CURRENT_BPPDAN_RESERVE, 
       cast (0 as Float) as CURRENT_MAIPARK_RESERVE, 
       cast (0 as Float) as CURRENT_DECREE_RESERVE, 
       cast (0 as Float) as CURRENT_QUOTASHARE_RESERVE, 
	   cast (0 as Float) as CURRENT_QUOTASHARE_SHORTFALL_RESERVE,
       cast (0 as Float) as CURRENT_SURPLUS_RESERVE, 
	   cast (0 as Float) as CURRENT_SURPLUS_SHORTFALL_RESERVE, 
       cast (0 as Float) as CURRENT_AUTOFAC_RESERVE, 
       cast (0 as Float) as CURRENT_FACULTATIVE_RESERVE, 
	   cast (0 as Float) as CURRENT_FACULTATIVEQS_RESERVE, 
	   cast (0 as Float) as CURRENT_FACULTATIVESP_RESERVE, 
	   cast (0 as Float) as CURRENT_FACULTATIVEAA_RESERVE, 

       cast (0 as Float) as CURRENT_EXPENSE_BPPDAN_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_MAIPARK_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_DECREE_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_QUOTASHARE_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_SURPLUS_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_AUTOFAC_RESERVE, 
       cast (0 as Float) as CURRENT_EXPENSE_FACULTATIVE_RESERVE, 

       cast (0 as Float) as CURRENT_XOL_RESERVE, 
       cast (0 as Float) as CURRENT_NET_RESERVE,
	   cast (0 as Float) as CURRENT_EXPENSE_NET_RESERVE

       from OS_CLAIM_BY_DETAIL(@P_PEDATE) O
	   Inner Join CArrHeader C on (C.CNO=O.CNO)
	   Inner join SysTab on (1=1)
) O      
Group By CNO, Branch, Currency, TOC      

)        
          


  
    
      
        
  
    
      
           
    


GO




DROP FUNCTION SETTLED_CLAIM_BY_DETAIL

GO

 
CREATE FUNCTION SETTLED_CLAIM_BY_DETAIL( @P_SDate as smalldatetime, @P_EDate as  smalldatetime)      
RETURNS TABLE       
AS RETURN (      
      
SELECT ANO, CNO, CURRENCY, TOC, BRANCH,      
SUM(CURRENT_GROSS_SETTLED-PREVIOUS_GROSS_SETTLED) AS GROSS_SETTLED,      
SUM(CURRENT_NET_SETTLED-PREVIOUS_NET_SETTLED) AS NET_SETTLED      
      
FROM       
(      
SELECT      
 CLAIM.ANO, CLAIM.CNO, CCALC.CURRENCY,COVER.TOC, ACCEPTANCE.BRANCH,      
 0 as PREVIOUS_GROSS_SETTLED,      
 0 as PREVIOUS_NET_SETTLED,      
 ((CCALC.CLAIM+CCALC.COST-CCALC.DEDUCTIBLE-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(1-CArrHeader.MShare/100)+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) as CURRENT_GROSS_SETTLED,      
 ((CCALC.CLAIM+CCALC.COST-CCALC.DEDUCTIBLE-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRShare/100)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) as CURRENT_NET_SETTLED      
FROM COVER, ACCEPTANCE, CLAIM, CCALC, CARRHEADER, RARRHEADER      
WHERE CLAIM.CSTATUS in ('A','C') and Claim.CType in ('N','E') and Claim.PCStatus in ('','A') and CLAIM.ADATE BETWEEN @P_SDATE and @P_EDATE AND ACCEPTANCE.ANO=CLAIM.ANO AND COVER.CNO=ACCEPTANCE.CNO AND CCALC.CNO=CLAIM.CNO AND CARRHEADER.CNO=CCALC.CNO AND RARRHEADER.ANO=CLAIM.ANO
UNION ALL      
      
SELECT      
 CLAIM.ANO, CLAIM.CNO, CCALC.CURRENCY,COVER.TOC, ACCEPTANCE.BRANCH,      
 ((CCALC.CLAIM+CCALC.COST-CCALC.DEDUCTIBLE-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100*(1-CArrHeader.MShare/100)+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) as PREVIOUS_GROSS_SETTLED,      
 ((CCALC.CLAIM+CCALC.COST-CCALC.DEDUCTIBLE-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRShare/100)+(CCALC.TCOST-CCALC.COST-CCALC.RCOST)-(CCALC.TSUBROGATION-CCALC.SUBROGATION-CCALC.RSUBROGATION)-(CCALC.TSALVAGE-CCALC.SALVAGE-CCALC.RSALVAGE) as PREVIOUS_NET_SETTLED,      
 0 as CURRENT_GROSS_SETTLED,      
 0 as CURRENT_NET_SETTLED      
FROM COVER, ACCEPTANCE, CLAIM CCLAIM, CLAIM, CCALC, CARRHEADER, RARRHEADER
WHERE CCLAIM.CSTATUS in ('A','C') and CCLAIM.CTYPE in ('C','E') and CCLAIM.PCStatus in ('','A') and CCLAIM.ADATE BETWEEN @P_SDATE and @P_EDATE AND CLAIM.CNO=CCLAIM.PCNO AND ACCEPTANCE.ANO=CLAIM.ANO AND COVER.CNO=ACCEPTANCE.CNO AND CCALC.CNO=CLAIM.CNO AND CARRHEADER.CNO=CCALC.CNO AND RARRHEADER.ANO=CLAIM.ANO    
) S       
      
GROUP BY ANO, CNO, CURRENCY, TOC, BRANCH      
      
      
)      
               
    
GO

DROP FUNCTION R_OS_CLAIM_DETAIL
GO
CREATE FUNCTION R_OS_CLAIM_DETAIL( @P_EDate as  smalldatetime)        
RETURNS @R_OS_CLAIM_DETAIL TABLE (ID varchar(10), DocNo varchar(50), Type varchar(2), ANO int, CNO int, OCNO int, REFNO varchar(50), Description varchar(255), Currency_OC varchar(10), Rate Float, Currency varchar(10), TOC varchar(10), Reserved Float, Expense_Reserved Float)      
AS      
BEGIN      
      
Declare @OS_CLAIM_BY_DETAIL Table(Payment varchar(10), CNO int, ANO int, OCNO int, Currency_OC varchar(10), Rate Float, Currency varchar(10), TOC varchar(10), ISType varchar(2), ClaimNo varchar(20), Gross_Loss Float, Gross_OS Float, Gross_Settled Float, Cost_Loss Float, Cost_OS Float, Cost_Settled Float, OWNSUBROGATION_OS FLoat, OWNSALVAGE_OS Float, Expense_OS Float, BPPDAN_OS Float, MAIPARK_OS Float, DECREE_OS Float, QUOTASHARE_OS Float, SURPLUS1_OS Float, SURPLUS2_OS Float, SURPLUS3_OS Float, AUTOFAC_OS Float, XOL1_OS Float, XOL2_OS Float, XOL3_OS Float, XOL4_OS Float, XOL5_OS Float, XOL6_OS Float, XOL7_OS Float, FACULTATIVE_OS Float, EXPENSE_BPPDAN_OS Float, EXPENSE_MAIPARK_OS Float, EXPENSE_DECREE_OS Float, EXPENSE_QUOTASHARE_OS Float, EXPENSE_SURPLUS1_OS Float, EXPENSE_SURPLUS2_OS Float, EXPENSE_SURPLUS3_OS Float, EXPENSE_AUTOFAC_OS Float, EXPENSE_FACULTATIVE_OS Float)      

insert into @OS_CLAIM_BY_DETAIL      
Select 
O.Payment, O.CNO, O.ANO, O.OCNO, O.Currency as Currency_OC, O.Rate, SysTab.Currency, O.TOC, O.ISType, O.ClaimNo
, O.Gross_Loss*O.Rate as Gross_Loss
, O.Gross_OS*O.Rate as Gross_OS
, O.Gross_Settled*O.Rate as Gross_Settled
, O.Cost_Loss*O.Rate as Cost_Loss
, O.Cost_OS*O.Rate as Cost_OS
, O.Cost_Settled*O.Rate as Cost_Settled
, O.OWNSUBROGATION_OS*O.Rate as OWNSUBROGATION_OS
, O.OWNSALVAGE_OS*O.Rate as OWNSALVAGE_OS
, O.Expense_OS*O.Rate as Expense_OS
, O.BPPDAN_OS*O.RATE as BPPDAN_OS
, O.MAIPARK_OS*O.RATE as MAIPARK_OS
, O.DECREE_OS*O.RATE as DECREE_OS
, O.QUOTASHARE_OS*O.RATE as QUOTASHARE_OS
, O.SURPLUS1_OS*O.RATE as SURPLUS1_OS
, O.SURPLUS2_OS*O.RATE as SURPLUS2_OS
, O.SURPLUS3_OS*O.RATE as SURPLUS3_OS
, O.AUTOFAC_OS*O.RATE as AUTOFAC_OS
, O.XOL1_OS*O.RATE as XOL1_OS
, O.XOL2_OS*O.RATE as XOL2_OS
, O.XOL3_OS*O.RATE as XOL3_OS
, O.XOL4_OS*O.RATE as XOL4_OS
, O.XOL5_OS*O.RATE as XOL5_OS
, O.XOL6_OS*O.RATE as XOL6_OS
, O.XOL7_OS*O.RATE as XOL7_OS
, O.FACULTATIVE_OS*O.RATE as FACULTATIVE_OS
, O.EXPENSE_BPPDAN_OS*O.RATE as EXPENSE_BPPDAN_OS
, O.EXPENSE_MAIPARK_OS*O.RATE as EXPENSE_MAIPARK_OS
, O.EXPENSE_DECREE_OS*O.RATE as EXPENSE_DECREE_OS
, O.EXPENSE_QUOTASHARE_OS*O.RATE as EXPENSE_QUOTASHARE_OS
, O.EXPENSE_SURPLUS1_OS*O.RATE as EXPENSE_SURPLUS1_OS
, O.EXPENSE_SURPLUS2_OS*O.RATE as EXPENSE_SURPLUS2_OS
, O.EXPENSE_SURPLUS3_OS*O.RATE as EXPENSE_SURPLUS3_OS
, O.EXPENSE_AUTOFAC_OS*O.RATE as EXPENSE_AUTOFAC_OS
, O.EXPENSE_FACULTATIVE_OS*O.RATE as EXPENSE_FACULTATIVE_OS
from OS_CLAIM_BY_DETAIL(@P_EDATE) O, SysTab    
      

-- INWARD BUSINESS      
Insert into @R_OS_CLAIM_DETAIL            
select O.Payment as ID, '' as DocNo, Case When O.ISType in ('C','L') then 'DI' else (Case When O.ISType in ('I') then 'IC' else (Case When O.ISType in ('R') then 'IR' else 'IT' end) end) end as Type, O.ANO, O.CNO, O.OCNO, O.CLAIMNO as REFNO, '--' as Description, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(O.GROSS_OS-O.COST_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O, RArrheader R Where R.ANO=O.ANO
GROUP BY O.Payment, Case When O.ISType in ('C','L') then 'DI' else (Case When O.ISType in ('I') then 'IC' else (Case When O.ISType in ('R') then 'IR' else 'IT' end) end) end, O.ANO, O.CNO, O.OCNO, O.CLAIMNO, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        

Insert into @R_OS_CLAIM_DETAIL  
select O.Payment as ID, '' as DocNo, 'CF' as Type, O.ANO, O.CNO, O.OCNO, O.CLAIMNO as REFNO, '--' as Description, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(O.GROSS_OS*-R.MShare/100) AS RESERVED, SUM(O.COST_OS*-R.MShare/100) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O, RArrheader R Where R.ANO=O.ANO
GROUP BY O.Payment, O.ANO, O.CNO, O.OCNO, O.CLAIMNO, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        

union All

select O.Payment as ID, '' as DocNo, 'OP' as Type, O.ANO, O.CNO, O.OCNO, O.CLAIMNO as REFNO, '--' as Description, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(O.EXPENSE_OS+O.COST_OS) AS RESERVED, SUM(O.EXPENSE_OS+O.COST_OS) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O, RArrheader R Where R.ANO=O.ANO
GROUP BY O.Payment, O.ANO, O.CNO, O.OCNO, O.CLAIMNO, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC   
Having SUM(O.EXPENSE_OS+O.COST_OS)<>0     
      
union all      
      
-- OUTWARD BUSINESS      
-- Compulsory      
select R2.ID, R2.DocNo, 'CP' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.BPPDAN_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_BPPDAN_OS) AS EXPENSE_RESERVED 
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.CID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          

      
union all             
      
-- Excess Priority      
select R2.ID, R2.DocNo, 'XP' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.MAIPARK_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_MAIPARK_OS) AS EXPENSE_RESERVED 
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.XPID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          
      
union all      
      
-- Decree      
        
select R2.ID, R2.DocNo, 'DC' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.DECREE_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_DECREE_OS) AS EXPENSE_RESERVED 
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.DID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          
      
union all      
      
-- Quota Share        
        
select R2.ID, R2.DocNo, 'QS' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.QUOTASHARE_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_QUOTASHARE_OS) AS EXPENSE_RESERVED  
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.QID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          
        
union all        
        
-- Surplus #1        
        
select R2.ID, R2.DocNo, 'S1' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS1_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_SURPLUS1_OS) AS EXPENSE_RESERVED 
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP1ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          
        
union all        
        
-- Surplus #2        
        
select R2.ID, R2.DocNo, 'S2' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS2_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_SURPLUS2_OS) AS EXPENSE_RESERVED 
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP2ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          
        
union all        
        
-- Surplus #3        
        
select R2.ID, R2.DocNo, 'S3' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS3_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_SURPLUS3_OS) AS EXPENSE_RESERVED 
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP3ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          
        
union all        
        
-- Auto Facultative        
        
select R2.ID, R2.DocNo, 'AF' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.AUTOFAC_OS) AS RESERVED, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_AUTOFAC_OS) AS RESERVED 
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.AID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC          

union all        
        
-- Facultative                
     
select R2.ID, R2.SlipNo as DocNo, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
) as Type,
O.ANO, O.CNO, O.OCNO, R2.SLIPNO as REFNO, 
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description,
O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.GROSS_LOSS*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.GROSS_SETTLED*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS RESERVED
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.Cost_Loss *
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.Cost_Settled *
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS EXPENSE_RESERVED
from @OS_CLAIM_BY_DETAIL O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)	 
Where R1.FullCoverF=1 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
AND O.FACULTATIVE_OS<>0
GROUP BY R2.ID, R2.SlipNo, O.ANO, O.CNO, O.OCNO, R2.SLIPNO, O.CURRENCY_OC, O.Rate, O.CURRENCY, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
),
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
),
O.TOC        

union all

select R2.ID, R2.SlipNo as DocNo, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
) as Type,
O.ANO, O.CNO, O.OCNO, R2.SLIPNO as REFNO, 
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description,
O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.GROSS_LOSS*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.GROSS_SETTLED*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS RESERVED
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.Cost_Loss *
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.Cost_Settled *
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS EXPENSE_RESERVED
from @OS_CLAIM_BY_DETAIL O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)
Inner Join FPartDet on (FPartDet.ANO=R2.ANO AND FPartDet.FID=R2.FID AND FPartDet.ID=R2.ID)

Cross Apply
(
	SELECT CCALC.CNO, SUM((CCALC.LOSS-CCALC.EDEDUCTIBLE-CCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((CCALC.CLAIM-CCALC.DEDUCTIBLE-CCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM CCALC
	Where CCALC.CNO=C.CNO
	GROUP BY CCALC.CNO
) CCALC 

Cross Apply
(
	SELECT LCALC.CNO, LCALC.TOR, SUM((LCALC.LOSS-LCALC.EDEDUCTIBLE-LCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((LCALC.INDEMNITY-LCALC.DEDUCTIBLE-LCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM LCALC, CCALC, COL
	WHERE CCALC.CNO=C.CNO AND CCALC.CNO=LCALC.CNO AND CCALC.CURRENCY=LCALC.CURRENCY
	AND COL.COL=C.COL AND COL.TOR=LCALC.TOR AND EXISTS (Select RateCov.Code from RateCov Where RateCov.Code=FPartDet.Code AND RateCov.TOR=LCALC.TOR)
	GROUP BY LCALC.CNO, LCALC.TOR
) LCALC

Outer Apply
(
	SELECT PCCALC.CNO, SUM((PCCALC.LOSS-PCCALC.EDEDUCTIBLE-PCCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PCCALC.CLAIM-PCCALC.DEDUCTIBLE-PCCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM CCALC PCCALC
	WHERE PCCALC.CNO=pClaim.CNO
	GROUP BY PCCALC.CNO
) PCCALC 


Outer Apply
(
	SELECT PLCALC.CNO, PLCALC.TOR, SUM((PLCALC.LOSS-PLCALC.EDEDUCTIBLE-PLCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PLCALC.INDEMNITY-PLCALC.DEDUCTIBLE-PLCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM LCALC PLCALC, CCALC PCCALC
	WHERE PLCALC.CNO=pClaim.CNO AND PLCALC.TOR=LCALC.TOR AND PCCALC.CNO=PLCALC.CNO AND PCCALC.CURRENCY=PLCALC.CURRENCY
	GROUP BY PLCALC.CNO, PLCALC.TOR
) PLCALC

Where R1.FullCoverF=0 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
AND O.FACULTATIVE_OS<>0
GROUP BY R2.ID, R2.SlipNo, O.ANO, O.CNO, O.OCNO, R2.SLIPNO, O.CURRENCY_OC, O.Rate, O.CURRENCY, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
),
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
),
O.TOC        

union all        
        
-- Excess Of Loss #Layer 1        
        
select R2.ID, R2.DocNo, 'X1' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL1ID) as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL1_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED        
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL1ID, pR.XL1ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL1ID), R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        
        
union all        
        
-- Excess Of Loss #Layer 2        

select R2.ID, R2.DocNo, 'X2' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL2ID) as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL2_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL2ID, pR.XL2ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL2ID), R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        
        
union all        
        
-- Excess Of Loss #Layer 3        
        
select R2.ID, R2.DocNo, 'X3' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL3ID) as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL3_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL3ID, pR.XL3ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL3ID), R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        
        
union all        
        
-- Excess Of Loss #Layer 4        
        
select R2.ID, R2.DocNo, 'X4' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL4ID) as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL4_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL4ID, pR.XL4ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL4ID), R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        
      
union all        
        
-- Excess Of Loss #Layer 5      
        
select R2.ID, R2.DocNo, 'X5' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL5ID) as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL5_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL5ID, pR.XL5ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL5ID), R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        
      
union all        
        
-- Excess Of Loss #Layer 6      
        
select R2.ID, R2.DocNo, 'X6' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL6ID) as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL6_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL6ID, pR.XL6ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL6ID), R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        
      
union all        
        
-- Excess Of Loss #Layer 7      
        
select R2.ID, R2.DocNo, 'X7' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL7ID) as REFNO, R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL7_OS) AS RESERVED, cast(0 as Float) as EXPENSE_RESERVED       
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL7ID, pR.XL7ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL7ID), R1.DESCRIPTION, O.CURRENCY_OC, O.Rate, O.CURRENCY, O.TOC        
        
Return      
      
end      
    
    
  
  
  
  
GO


DROP FUNCTION R_OS_CLAIM
GO
Create FUNCTION R_OS_CLAIM( @P_EDate as  smalldatetime)              
RETURNS @OS_CLAIM TABLE (OCNO int, Payment Varchar(10), ANO int, CNO int, CURRENCY varchar(10), TOC varchar(10), Branch Varchar(10), ISType varchar(1), ClaimNo varchar(20), 
GROSS_OS Float, CoOut_OS FLOAT, GROSS_OS_CLAIM FLOAT, DECREE_OS FLOAT, BPPDAN_OS FLOAT, MAIPARK_OS FLOAT, QUOTASHARE_OS FLOAT, SURPLUS_OS FLOAT, AUTOFAC_OS FLOAT, 
FACULTATIVE_OS FLOAT, GROSS_OS_XOL FLOAT, XOL1_OS Float, XOL2_OS Float, XOL3_OS FLoat, XOL4_OS Float, XOL5_OS Float, XOL6_OS Float, XOL7_OS Float, GROSS_LOSS float, GROSS_SETTLED float,GROSS_OS_NET FLOAT, ANR FLOAT, SETTLEDF bit,EXPENSE_OS Float)  
AS  
BEGIN  
insert into @OS_Claim      
SELECT 
O.OCNO, O.PAYMENT, ANO, O.CNO, O.CURRENCY, O.TOC, O.BRANCH, O.ISTYPE, O.CLAIMNO, 
O.GROSS_OS, 
(O.GROSS_OS*CR.MSHARE/100) AS CoOut_OS,
(O.GROSS_OS*(100-CR.MShare)/100+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS) AS GROSS_OS_CLAIM,
COALESCE(O.DECREE_OS,0) AS DECRESS_OS, 
COALESCE(O.BPPDAN_OS,0) AS BPPDAN_OS, 
COALESCE(O.MAIPARK_OS,0) AS MAIPARK_OS, 
COALESCE(O.QUOTASHARE_OS,0) AS QUOTASHARE_OS, 
coalesce(O.SURPLUS1_OS,0)+coalesce(O.SURPLUS2_OS,0)+coalesce(O.SURPLUS3_OS,0) as SURPLUS_OS, 
COALESCE(O.AUTOFAC_OS,0) AS AUTOFAC_OS, 
COALESCE(O.FACULTATIVE_OS,0) AS FACULTATIVE_OS, 
COALESCE(O.GROSS_OS_XOL,0) AS GROSS_OS_XOL,
COALESCE(O.XOL1_OS,0) AS XOL1_OS,
COALESCE(O.XOL2_OS,0) AS XOL2_OS,
COALESCE(O.XOL3_OS,0) AS XOL3_OS,
COALESCE(O.XOL4_OS,0) AS XOL4_OS,
COALESCE(O.XOL5_OS,0) AS XOL5_OS,
COALESCE(O.XOL6_OS,0) AS XOL6_OS,
COALESCE(O.XOL7_OS,0) AS XOL7_OS,
O.GROSS_LOSS, 
O.GROSS_SETTLED, 
O.GROSS_OS_NET AS GROSS_OS_NET,
(O.GROSS_OS_NET+O.EXPENSE_OS+O.OWNSUBROGATION_OS+O.OWNSALVAGE_OS+O.SURPLUSSF_OS) AS ANR,
0 as SETTLEDF, 
O.EXPENSE_OS
FROM OS_CLAIM_BY_DETAIL(@P_EDATE) O, CarrHeader CR
WHERE O.CNO=CR.CNO    

insert into @OS_Claim          
Select       
 CLAIM.OCNO, CLAIM.PAYMENT, CLAIM.ANO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,

  0 as GROSS_OS,
  0 AS CoOut_OS,
  0 AS GROSS_OS_CLAIM,
  0 as DECREE_OS, 
  0 AS BPPDAN_OS, 
  0 AS MAIPARK_OS, 
  0 AS QUOTASHARE_OS, 
  0 AS SURPLUS_OS, 
  0 AS AUTOFAC_OS, 
  0 AS FACULTATIVE_OS, 
  0 AS GROSS_OS_XOL,
  0 AS XOL1_OS,
  0 AS XOL2_OS,
  0 AS XOL3_OS,
  0 AS XOL4_OS,
  0 AS XOL5_OS,
  0 AS XOL6_OS,
  0 AS XOL7_OS,
 ((CCALC.LOSS-CCALC.EDEDUCTIBLE+CCALC.ECOST-CCALC.ESALVAGE-CCALC.ESUBROGATION)*CCALC.SHARE/100+CCALC.ERCOST-CCALC.ERSUBROGATION-CCALC.ERSALVAGE) AS GROSS_LOSS,  
      
 (Case When PCStatus='P' and Month(Claim.CSDate)=MONTH(@P_EDATE) and Year(Claim.CSDate)=Year(@P_EDate) then    
 0  
 else    
  ((CCALC.CLAIM-CCALC.DEDUCTIBLE+CCALC.COST-CCALC.SALVAGE-CCALC.SUBROGATION)*CCALC.SHARE/100+CCALC.RCOST-CCALC.RSUBROGATION-CCALC.RSALVAGE) End) AS GROSS_SETTLED,  
 0 AS GROSS_OS_NET,
 0 AS ANR,
 1 as SETTLEDF,
 0 as EXPENSE_OS
FROM CLAIM INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=CLAIM.PCNO AND PCCALC.CURRENCY=CCALC.CURRENCY)              
     INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO)    
WHERE CLAIM.REGDATE<=@P_EDATE AND CLAIM.CTYPE<>'C' AND CLAIM.CSTATUS<>'R'     
AND (CLAIM.PSETTLEDF=0 AND CLAIM.SETTLEDF=1 AND MONTH((Case When Claim.PCStatus='P' then Claim.CSDate else Claim.ADate end))=MONTH(@P_EDATE) and YEAR((Case When Claim.PCStatus='P' then Claim.CSDate else Claim.ADate end))=YEAR(@P_EDATE))                 
AND OCNO NOT IN (SELECT OCNO from @OS_CLAIM)  
RETURN  
End  
    

GO

DROP FUNCTION R_OS_CLAIM_REINSURANCE
GO
CREATE FUNCTION R_OS_CLAIM_REINSURANCE (@P_EDate as  smalldatetime)      
RETURNS @R_OS_CLAIM_REINSURANCE TABLE (ID varchar(10), DocNo varchar(50), RID varchar(20), RTYPE varchar(2), Description varchar(255), Currency varchar(10), TOC varchar(10), Estimate Float, Reserved Float)    
AS    
BEGIN    
    
Declare @OS_CLAIM_BY_DETAIL Table (Payment varchar(10), CNO int, ANO int, Currency varchar(10), TOC varchar(10), ISType varchar(2), ClaimNo varchar(20), Gross_Loss Float, Gross_OS Float, Gross_Settled Float, Cost_Loss Float, Cost_OS Float, Cost_Settled Float, BPPDAN_OS Float, MAIPARK_OS Float, DECREE_OS Float, QUOTASHARE_OS Float, SURPLUS1_OS Float, SURPLUS2_OS Float, SURPLUS3_OS Float, AUTOFAC_OS Float, XOL1_OS Float, XOL2_OS Float, XOL3_OS Float, XOL4_OS Float, XOL5_OS Float, XOL6_OS Float, XOL7_OS Float, FACULTATIVE_OS Float)    
insert into @OS_CLAIM_BY_DETAIL    
Select Payment, CNO, ANO, SysTab.Currency, TOC, ISType, ClaimNo
, Gross_Loss*Rate as Gross_Loss
, Gross_OS*Rate as Gross_OS
, Gross_Settled*Rate as Gross_Settled
, O.Cost_Loss*Rate as Cost_Loss
, O.Cost_OS*Rate as Cost_OS
, O.Cost_Settled*Rate as Cost_Settled
, O.BPPDAN_OS*O.RATE as BPPDAN_OS
, O.MAIPARK_OS*O.RATE as MAIPARK_OS
, O.DECREE_OS*O.RATE as DECREE_OS
, O.QUOTASHARE_OS*O.RATE as QUOTASHARE_OS
, O.SURPLUS1_OS*O.RATE as SURPLUS1_OS
, O.SURPLUS2_OS*O.RATE as SURPLUS2_OS
, O.SURPLUS3_OS*O.RATE as SURPLUS3_OS
, O.AUTOFAC_OS*O.RATE as AUTOFAC_OS
, O.XOL1_OS*O.RATE as XOL1_OS
, O.XOL2_OS*O.RATE as XOL2_OS
, O.XOL3_OS*O.RATE as XOL3_OS
, O.XOL4_OS*O.RATE as XOL4_OS
, O.XOL5_OS*O.RATE as XOL5_OS
, O.XOL6_OS*O.RATE as XOL6_OS
, O.XOL7_OS*O.RATE as XOL7_OS
, O.FACULTATIVE_OS*O.RATE as FACULTATIVE_OS
from OS_CLAIM_BY_DETAIL(@P_EDATE) O, SysTab  

    
-- Compulsory    
INSERT INTO @R_OS_CLAIM_REINSURANCE      
select R2.ID, R2.DocNo, R.CID, MAX(coalesce(R1.RTYPE,'C')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.BPPDAN_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.CID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.CID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
    
-- Decree    
      
select R2.ID, R2.DocNo, R.DID, MAX(coalesce(R1.RTYPE,'D')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.DECREE_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.DID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.DID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
    
-- Excess Priority    
      
select R2.ID, R2.DocNo, R.XPID, MAX(coalesce(R1.RTYPE,'XP')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.MAIPARK_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.XPID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.XPID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
 
      
union all      
    
      
-- Quota Share      
select R2.ID, R2.DocNo, R.QID, MAX(coalesce(R1.RTYPE,'Q')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.QUOTASHARE_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.QID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.QID, R1.DESCRIPTION, O.CURRENCY, O.TOC         
      
union all      
      
-- Surplus #1      
      
select R2.ID, R2.DocNo, R.SP1ID, MAX(coalesce(R1.RTYPE,'S1')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS1_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP1ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.SP1ID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
      
-- Surplus #2      
      
select R2.ID, R2.DocNo, R.SP2ID, MAX(coalesce(R1.RTYPE,'S2')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS2_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP2ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.SP2ID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
   
      
union all      
      
-- Surplus #3      
      
select R2.ID, R2.DocNo, R.SP3ID, MAX(coalesce(R1.RTYPE,'S3')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS3_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP3ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.SP3ID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
      
-- Auto Facultative      
      
select R2.ID, R2.DocNo, R.AID, MAX(coalesce(R1.RTYPE,'A')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.AUTOFAC_OS) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.AID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, R.AID, R1.DESCRIPTION, O.CURRENCY, O.TOC        
      
union all      
      
-- Facultative      
      
select R2.ID, R2.SlipNo as DocNo, R1.FID as RID, 
(
Case 
When R1.RType in ('QS') Then 'Q'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'A'
Else 'F' End
) as RType,
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description, 
O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.GROSS_LOSS*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.GROSS_SETTLED*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS REINSURANCE
from @OS_CLAIM_BY_DETAIL O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)	 
Where R1.FullCoverF=1 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
GROUP BY R2.ID, R2.SlipNo, R1.FID, O.CURRENCY, 
(
Case 
When R1.RType in ('QS') Then 'Q'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'A'
Else 'F' End
),
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
),
O.TOC      

union all

select R2.ID, R2.SlipNo as DocNo, R1.FID as RID, 
(
Case 
When R1.RType in ('QS') Then 'Q'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'A'
Else 'F' End
) as RType,
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description, 
O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.GROSS_LOSS*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.GROSS_SETTLED*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)
Inner Join FPartDet on (FPartDet.ANO=R2.ANO AND FPartDet.FID=R2.FID AND FPartDet.ID=R2.ID)

Cross Apply
(
	SELECT CCALC.CNO, SUM((CCALC.LOSS-CCALC.EDEDUCTIBLE-CCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((CCALC.CLAIM-CCALC.DEDUCTIBLE-CCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM CCALC
	Where CCALC.CNO=C.CNO
	GROUP BY CCALC.CNO
) CCALC 

Cross Apply
(
	SELECT LCALC.CNO, LCALC.TOR, SUM((LCALC.LOSS-LCALC.EDEDUCTIBLE-LCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((LCALC.INDEMNITY-LCALC.DEDUCTIBLE-LCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM LCALC, CCALC, COL
	WHERE CCALC.CNO=C.CNO AND CCALC.CNO=LCALC.CNO AND CCALC.CURRENCY=LCALC.CURRENCY
	AND COL.COL=C.COL AND COL.TOR=LCALC.TOR AND EXISTS (Select RateCov.Code from RateCov Where RateCov.Code=FPartDet.Code AND RateCov.TOR=LCALC.TOR)
	GROUP BY LCALC.CNO, LCALC.TOR
) LCALC

Outer Apply
(
	SELECT PCCALC.CNO, SUM((PCCALC.LOSS-PCCALC.EDEDUCTIBLE-PCCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PCCALC.CLAIM-PCCALC.DEDUCTIBLE-PCCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM CCALC PCCALC
	WHERE PCCALC.CNO=pClaim.CNO
	GROUP BY PCCALC.CNO
) PCCALC 


Outer Apply
(
	SELECT PLCALC.CNO, PLCALC.TOR, SUM((PLCALC.LOSS-PLCALC.EDEDUCTIBLE-PLCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PLCALC.INDEMNITY-PLCALC.DEDUCTIBLE-PLCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM LCALC PLCALC, CCALC PCCALC
	WHERE PLCALC.CNO=pClaim.CNO AND PLCALC.TOR=LCALC.TOR AND PCCALC.CNO=PLCALC.CNO AND PCCALC.CURRENCY=PLCALC.CURRENCY
	GROUP BY PLCALC.CNO, PLCALC.TOR
) PLCALC

Where R1.FullCoverF=0 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
GROUP BY R2.ID, R2.SlipNo, R1.FID, O.CURRENCY, 
(
Case 
When R1.RType in ('QS') Then 'Q'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'A'
Else 'F' End
),
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
),
O.TOC      
          
union all      
      
-- Excess Of Loss #Layer 1      

select R2.ID, R2.DocNo, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.XOL1_OS) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL1ID, pR.XL1ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC 
           
union all      
      
-- Excess Of Loss #Layer 2      
      
select R2.ID, R2.DocNo, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.XOL2_OS) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL2ID, pR.XL2ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
      
union all      
      
-- Excess Of Loss #Layer 3      
      
select R2.ID, R2.DocNo, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.XOL3_OS) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL3ID, pR.XL3ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
      
union all      
      
-- Excess Of Loss #Layer 4      
      
select R2.ID, R2.DocNo, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.XOL4_OS) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL4ID, pR.XL4ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
    
union all      
      
-- Excess Of Loss #Layer 5    
      
select R2.ID, R2.DocNo, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.XOL5_OS) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL5ID, pR.XL5ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
    
union all      
      
-- Excess Of Loss #Layer 6    
      
select R2.ID, R2.DocNo, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.XOL6_OS) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL6ID, pR.XL6ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
    
union all      
      
-- Excess Of Loss #Layer 7    
      
select R2.ID, R2.DocNo, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_OS) AS ESTIMATE, SUM(coalesce(R2.SHARE,100)/100*O.XOL7_OS) AS REINSURANCE     
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL7ID, pR.XL7ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
      
Return    
    
End     

GO

DROP FUNCTION R_OS_CLAIM_REINSURANCE_DETAIL
GO
CREATE FUNCTION R_OS_CLAIM_REINSURANCE_DETAIL( @P_EDate as  smalldatetime)      
RETURNS @R_OS_CLAIM_REINSURANCE_DETAIL TABLE (ID varchar(10), DocNo varchar(50), CNO int, ANO int, RID varchar(20), RTYPE varchar(2), Description varchar(255), Currency varchar(10), TOC varchar(10), Loss Float, Estimate Float, Settled Float, Reserved Float, Expense_OS Float, Share Float)    
AS    
BEGIN    
    
Declare @OS_CLAIM_BY_DETAIL Table(Payment varchar(10), CNO int, ANO int, Currency varchar(10), Rate Float, TOC varchar(10), ISType varchar(2), ClaimNo varchar(20), Gross_Loss Float, Gross_OS Float, Gross_Settled Float, Cost_Loss Float, Cost_OS Float, Cost_Settled Float, BPPDAN_OS Float, MAIPARK_OS Float, DECREE_OS Float, QUOTASHARE_OS Float, SURPLUS1_OS Float, SURPLUS2_OS Float, SURPLUS3_OS Float, AUTOFAC_OS Float, EXPENSE_BPPDAN_OS Float, EXPENSE_MAIPARK_OS Float, EXPENSE_DECREE_OS Float, EXPENSE_QUOTASHARE_OS Float, EXPENSE_SURPLUS1_OS Float, EXPENSE_SURPLUS2_OS Float, EXPENSE_SURPLUS3_OS Float, EXPENSE_AUTOFAC_OS Float, XOL1_OS Float, XOL2_OS Float, XOL3_OS Float, XOL4_OS Float, XOL5_OS Float, XOL6_OS Float, XOL7_OS Float, FACULTATIVE_OS Float)    
insert into @OS_CLAIM_BY_DETAIL    
Select O.Payment, O.CNO, O.ANO, O.Currency, O.Rate, O.TOC, O.ISType, O.ClaimNo
, O.Gross_Loss as Gross_Loss
, O.Gross_OS as Gross_OS
, O.Gross_Settled as Gross_Settled
, O.Cost_Loss as Cost_Loss
, O.Cost_OS as Cost_OS
, O.Cost_Settled as Cost_Settled
, O.BPPDAN_OS as BPPDAN_OS
, O.MAIPARK_OS as MAIPARK_OS
, O.DECREE_OS as DECREE_OS
, O.QUOTASHARE_OS as QUOTASHARE_OS
, O.SURPLUS1_OS as SURPLUS1_OS
, O.SURPLUS2_OS as SURPLUS2_OS
, O.SURPLUS3_OS as SURPLUS3_OS
, O.AUTOFAC_OS as AUTOFAC_OS
, O.EXPENSE_BPPDAN_OS as EXPENSE_BPPDAN_OS
, O.EXPENSE_MAIPARK_OS as EXPENSE_MAIPARK_OS
, O.EXPENSE_DECREE_OS as EXPENSE_DECREE_OS
, O.EXPENSE_QUOTASHARE_OS as EXPENSE_QUOTASHARE_OS
, O.EXPENSE_SURPLUS1_OS as EXPENSE_SURPLUS1_OS
, O.EXPENSE_SURPLUS2_OS as EXPENSE_SURPLUS2_OS
, O.EXPENSE_SURPLUS3_OS as EXPENSE_SURPLUS3_OS
, O.EXPENSE_AUTOFAC_OS as EXPENSE_AUTOFAC_OS
, O.XOL1_OS as XOL1_OS
, O.XOL2_OS as XOL2_OS
, O.XOL3_OS as XOL3_OS
, O.XOL4_OS as XOL4_OS
, O.XOL5_OS as XOL5_OS
, O.XOL6_OS as XOL6_OS
, O.XOL7_OS as XOL7_OS
, O.FACULTATIVE_OS as FACULTATIVE_OS
from OS_CLAIM_BY_DETAIL(@P_EDATE) O

Insert into @R_OS_CLAIM_REINSURANCE_DETAIL    
    
-- Compulsory    
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.CID, MAX(coalesce(R1.RTYPE,'C')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.BPPDAN_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_BPPDAN_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.CID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R.CID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
    
-- Decree    
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.DID, MAX(coalesce(R1.RTYPE,'D')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.DECREE_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_DECREE_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.DID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R.DID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
    
-- Excess Priority    
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.XPID, MAX(coalesce(R1.RTYPE,'XP')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.MAIPARK_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_MAIPARK_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.XPID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R.XPID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
 
      
union all      
    
      
-- Quota Share      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.QID, MAX(coalesce(R1.RTYPE,'Q')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.QUOTASHARE_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_QUOTASHARE_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.QID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R.QID, R1.DESCRIPTION, O.CURRENCY, O.TOC         
      
union all      
      
-- Surplus #1      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.SP1ID, MAX(coalesce(R1.RTYPE,'S1')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS1_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_SURPLUS1_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP1ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R.SP1ID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
      
-- Surplus #2      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.SP2ID, MAX(coalesce(R1.RTYPE,'S2')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS2_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_SURPLUS2_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP2ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R.SP2ID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
   
      
union all      
      
-- Surplus #3      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.SP3ID, MAX(coalesce(R1.RTYPE,'S3')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS3_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_SURPLUS3_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP3ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R.SP3ID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
      
-- Auto Facultative      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R.AID, MAX(coalesce(R1.RTYPE,'A')), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(coalesce(R2.SHARE,100)/100*O.AUTOFAC_OS) AS REINSURANCE, SUM(coalesce(R2.SHARE,100)/100*O.EXPENSE_AUTOFAC_OS) AS EXPENSE, Max(coalesce(R2.SHARE,100))
from @OS_CLAIM_BY_DETAIL O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.AID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID,R2.DocNo,  O.CNO, O.ANO, R.AID, R1.DESCRIPTION, O.CURRENCY, O.TOC          
 
union all      
      
-- Facultative      
         
select R2.ID, R2.SlipNo as DocNo, O.CNO, O.ANO, R1.FID as RID, 
Max(
Case 
When R1.RType in ('QS') Then 'Q'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'A'
Else 'F' End
) as RType,
Max(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description, 
O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.GROSS_LOSS*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.GROSS_SETTLED*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS REINSURANCE
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.Cost_Loss *
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.Cost_Settled*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS EXPENSE
, Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)	 
Where R1.FullCoverF=1 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
GROUP BY R2.ID, R2.SlipNo, O.CNO, O.ANO, R1.FID, O.CURRENCY, O.TOC      

union all

select R2.ID, R2.SlipNo as DocNo, O.CNO, O.ANO, R1.FID as RID, 
Max(
Case 
When R1.RType in ('QS') Then 'Q'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'A'
Else 'F' End
) as RType,
Max(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description, 
O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.GROSS_LOSS*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.GROSS_SETTLED*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS REINSURANCE     
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.Cost_Loss *
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.Cost_Settled *
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS EXPENSE     
, Max(R2.Share)

from @OS_CLAIM_BY_DETAIL O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)
Inner Join FPartDet on (FPartDet.ANO=R2.ANO AND FPartDet.FID=R2.FID AND FPartDet.ID=R2.ID)

Cross Apply
(
	SELECT CCALC.CNO, SUM((CCALC.LOSS-CCALC.EDEDUCTIBLE-CCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((CCALC.CLAIM-CCALC.DEDUCTIBLE-CCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM CCALC
	Where CCALC.CNO=C.CNO
	GROUP BY CCALC.CNO
) CCALC 

Cross Apply
(
	SELECT LCALC.CNO, LCALC.TOR, SUM((LCALC.LOSS-LCALC.EDEDUCTIBLE-LCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((LCALC.INDEMNITY-LCALC.DEDUCTIBLE-LCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM LCALC, CCALC, COL
	WHERE CCALC.CNO=C.CNO AND CCALC.CNO=LCALC.CNO AND CCALC.CURRENCY=LCALC.CURRENCY
	AND COL.COL=C.COL AND COL.TOR=LCALC.TOR AND EXISTS (Select RateCov.Code from RateCov Where RateCov.Code=FPartDet.Code AND RateCov.TOR=LCALC.TOR)
	GROUP BY LCALC.CNO, LCALC.TOR
) LCALC

Outer Apply
(
	SELECT PCCALC.CNO, SUM((PCCALC.LOSS-PCCALC.EDEDUCTIBLE-PCCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PCCALC.CLAIM-PCCALC.DEDUCTIBLE-PCCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM CCALC PCCALC
	WHERE PCCALC.CNO=pClaim.CNO
	GROUP BY PCCALC.CNO
) PCCALC 


Outer Apply
(
	SELECT PLCALC.CNO, PLCALC.TOR, SUM((PLCALC.LOSS-PLCALC.EDEDUCTIBLE-PLCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PLCALC.INDEMNITY-PLCALC.DEDUCTIBLE-PLCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM LCALC PLCALC, CCALC PCCALC
	WHERE PLCALC.CNO=pClaim.CNO AND PLCALC.TOR=LCALC.TOR AND PCCALC.CNO=PLCALC.CNO AND PCCALC.CURRENCY=PLCALC.CURRENCY
	GROUP BY PLCALC.CNO, PLCALC.TOR
) PLCALC

Where R1.FullCoverF=0 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
GROUP BY R2.ID, R2.SlipNo, O.CNO, O.ANO, R1.FID, O.CURRENCY, O.TOC      

      
union all      
      
-- Excess Of Loss #Layer 1      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(R2.SHARE/100*O.XOL1_OS) AS REINSURANCE, cast(0 as Float), Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL1ID, pR.XL1ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
      
union all      
      
-- Excess Of Loss #Layer 2      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(R2.SHARE/100*O.XOL2_OS) AS REINSURANCE, cast(0 as Float), Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL2ID, pR.XL2ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
      
union all      
      
-- Excess Of Loss #Layer 3      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(R2.SHARE/100*O.XOL3_OS) AS REINSURANCE, cast(0 as Float), Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL3ID, pR.XL3ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
      
union all      
      
-- Excess Of Loss #Layer 4      
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(R2.SHARE/100*O.XOL4_OS) AS REINSURANCE, cast(0 as Float), Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL4ID, pR.XL4ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
    
union all      
      
-- Excess Of Loss #Layer 5    
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(R2.SHARE/100*O.XOL5_OS) AS REINSURANCE, cast(0 as Float), Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL5ID, pR.XL5ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
    
union all      
      
-- Excess Of Loss #Layer 6    
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(R2.SHARE/100*O.XOL6_OS) AS REINSURANCE, cast(0 as Float), Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL6ID, pR.XL6ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
    
union all      
      
-- Excess Of Loss #Layer 7    
      
select R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, MAX(R1.RTYPE), R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(O.GROSS_LOSS) AS LOSS, SUM(O.GROSS_OS) AS ESTIMATE, SUM(O.GROSS_SETTLED) AS SETTLED, SUM(R2.SHARE/100*O.XOL7_OS) AS REINSURANCE, cast(0 as Float), Max(R2.Share)
from @OS_CLAIM_BY_DETAIL O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL7ID, pR.XL7ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.CNO, O.ANO, R1.RID, R1.DESCRIPTION, O.CURRENCY, O.TOC      
      
Return    
    
End     
      
