GO

CREATE FUNCTION R_OS_CLAIM_REINSURANCE_SECURITY_DETAIL( @P_EDate as  smalldatetime)    
RETURNS TABLE                         
AS RETURN (                        
  
SELECT R.ID, R.CNO, R.ANO, R.RID, R.RTYPE, R.Description, R.Currency, R.TOC, R.LOSS, R.ESTIMATE, R.SETTLED, R.RESERVED, 
coalesce(sProfile.ID, fProfile.ID) as SID,
coalesce(Security.Share,coalesce(FSecurity.Share,100)) Share
From R_OS_CLAIM_REINSURANCE_DETAIL(@P_EDATE) R
Inner Join Claim on (Claim.CNO=R.CNO)
Inner Join fn_exchange(@P_EDate) Currency on (Currency.Currency=R.Currency)
Left Join Profile on (Profile.ID=R.ID)
---- Added For Reinsurance Security
Left Join Reinsurance on (R.RType in ('C','XP','D','Q','S1','S2','S3','A') and Reinsurance.RID=R.RID)
Left Join RPart on (RPart.RNO=Reinsurance.RNO and RPart.ID=R.ID and RPart.DocNo=R.DocNo)
Left Join Security on (Security.RNO=RPart.RNO and Security.ID=RPart.ID and Security.DocNo=RPart.DocNo and Security.Share<>0)
Left Join Profile sProfile on (sProfile.ID=Security.SID)

--Added For Facultative Security
Left Join FPart on (FPart.ANO=R.ANO and FPart.FID=R.RID and FPart.ID=R.ID)
Left Join FSecurity on (FSecurity.ANO=FPart.ANO and FSecurity.FID=FPart.FID and FSecurity.Share<>0)
Left Join Profile fProfile on (fProfile.ID=FSecurity.ID)

  
)   

