DROP FUNCTION R_OS_CLAIM_EXPENSE

GO

Create FUNCTION R_OS_CLAIM_EXPENSE( @P_EDate as  smalldatetime)                
RETURNS @OS_CLAIM TABLE (OCNO int, CCTYPE Varchar(10), Payment Varchar(10), ANO int, CNO int, RefNo varchar(50), CURRENCY varchar(10), TOC varchar(10), Branch Varchar(10), ISType varchar(1), ClaimNo varchar(20), GROSS_OS Float, GROSS_LOSS float, GROSS_SETTLED float, SETTLEDF bit,EXPENSE_OS Float)    
AS    
BEGIN    
    
insert into @OS_Claim        
SELECT OCNO, CCTYPE, PAYMENT, ANO, CNO, RefNo, CURRENCY, TOC, BRANCH, ISTYPE, CLAIMNO, GROSS_OS, GROSS_LOSS, GROSS_SETTLED, 0 as SETTLEDF, EXPENSE_OS  
FROM OS_CLAIM_BY_DETAIL_LOSS_EXPENSE(@P_EDATE)            
    
insert into @OS_Claim            
Select         
 CLAIM.OCNO, CLCOST.CCTYPE, CLCOST.ID AS PAYMENT, CLAIM.ANO, CLAIM.CNO, CLCOST.RefNo, CLCOST.CURRENCY, CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,          
 0 as GROSS_OS,      

(CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100) AS GROSS_LOSS,     

 Case When CLAIM.PCStatus='P' and Month(Claim.CSDate)=MONTH(@P_EDATE) and Year(Claim.CSDate)=Year(@P_EDate) then      
	0    
 else      
  (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END) END)/100) 
 End AS GROSS_SETTLED,    
 1 as SETTLEDF,  
 0 as EXPENSE_OS  

FROM CLAIM 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
LEFT JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO)
INNER JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) CLCOST ON (CLCOST.CNO=CCALC.CNO AND CLCOST.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) PCLCOST ON (PCLCOST.CNO=CLAIM.PCNO AND PCLCOST.ID=CLCOST.ID AND PCLCOST.Currency=CLCOST.Currency and PCLCOST.RefNo=CLCost.RefNo and PCLCost.CCType=CLCOST.CCTYPE)
LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=PCLCOST.CNO AND PCCALC.CURRENCY=PCLCOST.CURRENCY)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
WHERE CLAIM.REGDATE<=@P_EDATE AND CLAIM.CTYPE<>'C' AND CLAIM.CSTATUS<>'R'       
AND (CLAIM.PSETTLEDF=0 AND CLAIM.SETTLEDF=1 AND MONTH((Case When Claim.PCStatus='P' then Claim.CSDate else Claim.ADate end))=MONTH(@P_EDATE) and YEAR((Case When Claim.PCStatus='P' then Claim.CSDate else Claim.ADate end))=YEAR(@P_EDATE))                   
AND CLAIM.OCNO NOT IN (SELECT OCNO from @OS_CLAIM)    
RETURN    
End    

GO

Drop FUNCTION R_OS_CLAIM_PAYMENT

GO  
Create FUNCTION R_OS_CLAIM_PAYMENT( @P_EDate as  smalldatetime)                  
RETURNS @OS_CLAIM TABLE (OCNO int, Payment Varchar(10), RefNo Varchar(50), ANO int, CNO int, CURRENCY varchar(10), TOC varchar(10), Branch Varchar(10), ISType varchar(1), ClaimNo varchar(20), GROSS_OS Float, GROSS_LOSS float, GROSS_SETTLED float, SETTLEDF bit, EXPENSE_OS Float)      
AS      
BEGIN      
      
insert into @OS_Claim          
SELECT OCNO, PAYMENT, REFNO, ANO, CNO, CURRENCY, TOC, BRANCH, ISTYPE, CLAIMNO, GROSS_OS, GROSS_LOSS, GROSS_SETTLED, 0 as SETTLEDF, 0 as EXPENSE_OS    
FROM OS_CLAIM_BY_DETAIL_LOSS_PAYMENT(@P_EDATE)              
      
insert into @OS_Claim              


Select           
 CLAIM.OCNO, COALESCE(CLLOSS.PAYMENT, CLDED.ID) AS PAYMENT, CLLOSS.REFNO, CLAIM.ANO, CLAIM.CNO, COALESCE(CLLOSS.CURRENCY, CLDED.CURRENCY), CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,            
 0 as GROSS_OS,        
  
(CLLOSS.ESTIMATE*CCALC.SHARE/100) AS GROSS_LOSS,       
  
 Case When CLAIM.PCStatus='P' and Month(Claim.CSDate)=MONTH(@P_EDATE) and Year(Claim.CSDate)=Year(@P_EDate) then        
 0      
 else        
  (CLLOSS.AMOUNT*CCALC.SHARE/100)  
 End AS GROSS_SETTLED,      
 
 
 1 as SETTLEDF,    
 0 as EXPENSE_OS    
  
FROM CLAIM 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
LEFT JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO)
INNER JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.REFNO, CLLOSS.CURRENCY, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.REFNO, CLLOSS.CURRENCY) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.REFNO=CLLOSS.REFNO AND CLDED.ID=CLLOSS.PAYMENT)
LEFT JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.REFNO, CLLOSS.CURRENCY, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.REFNO, CLLOSS.CURRENCY) PCLLOSS ON (PCLLOSS.CNO=CLAIM.PCNO AND PCLLOSS.PAYMENT=CLLOSS.PAYMENT AND PCLLOSS.CURRENCY=CLLOSS.CURRENCY)
LEFT JOIN CCALC PCCALC ON (PCCALC.CNO=PCLLOSS.CNO AND PCCALC.CURRENCY=PCLLOSS.CURRENCY)
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) PCLDED ON (PCLDED.CNO=PCLLOSS.CNO AND PCLDED.CURRENCY=PCLLOSS.CURRENCY AND PCLDED.REFNO=PCLLOSS.REFNO AND PCLDED.ID=PCLLOSS.PAYMENT)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO)  
WHERE CLAIM.REGDATE<=@P_EDATE AND CLAIM.CTYPE<>'C' AND CLAIM.CSTATUS<>'R'       
AND (CLAIM.PSETTLEDF=0 AND CLAIM.SETTLEDF=1 AND MONTH((Case When Claim.PCStatus='P' then Claim.CSDate else Claim.ADate end))=MONTH(@P_EDATE) and YEAR((Case When Claim.PCStatus='P' then Claim.CSDate else Claim.ADate end))=YEAR(@P_EDATE))                   
AND CLAIM.OCNO NOT IN (SELECT OCNO from @OS_CLAIM)    
RETURN      
End      

GO

DROP FUNCTION CLAIM_REGISTER_BY_DETAIL_LOSS_PAYMENT
GO 
CREATE FUNCTION CLAIM_REGISTER_BY_DETAIL_LOSS_PAYMENT(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                        
RETURNS TABLE                         
AS RETURN (                                 
Select         
 Claim.RegDate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLLOSS.REFNO, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,                  
((CLLOSS.ESTIMATE)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100) AS CLAIM_REGISTER,        
(((CLLOSS.ESTIMATE)*CCALC.SHARE/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)) AS CLAIM_REGISTER_NET    
from Claim 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
INNER JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS WHERE EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.REFNO=CLLOSS.REFNO AND CLDED.ID=CLLOSS.PAYMENT)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)     
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and Claim.CType<>'C' and Claim.Cstatus<>'R' and Claim.PCStatus<>'R'        
        
UNION ALL        

Select         
 Claim.RegDate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLLOSS.REFNO, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY,PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                  
-((CLLOSS.ESTIMATE)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100) AS CLAIM_REGISTER,    
-(((CLLOSS.ESTIMATE)*CCALC.SHARE/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)) AS CLAIM_REGISTER_NET    
from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
INNER JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS WHERE EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.REFNO=CLLOSS.REFNO AND CLDED.ID=CLLOSS.PAYMENT)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0  and Claim.CType<>'C' and Claim.CStatus<>'R' and Claim.PCStatus<>'R'        
AND pClaim.CType<>'C' and not (PCLAIM.CStatus='C' AND PCLAIM.PCStatus='P')

UNION ALL        

Select         
 Claim.RegDate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLLOSS.REFNO, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY,PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                  

 ((CLLOSS.ESTIMATE)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100)
- (CASE WHEN PCLAIM.SettledF=1 and PCLAIM.CStatus in ('C','A') and PCLAIM.PCStatus in ('','A') and PCLAIM.CType in ('N','E') Then (((CLLOSS.AMOUNT)*CCALC.SHARE/100)*(100-CARRHEADER.MSHARE)/100) else 0 end)  AS CLAIM_REGISTER,    

(((CLLOSS.ESTIMATE)*CCALC.SHARE/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100))
- (CASE WHEN PCLAIM.SettledF=1 and PCLAIM.CStatus in ('C','A') and PCLAIM.PCStatus in ('','A') and PCLAIM.CType in ('N','E') Then (((CLLOSS.AMOUNT)*CCALC.SHARE/100)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRSHARE/100)) else 0 end)  AS CLAIM_REGISTER_NET        

from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
INNER JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS WHERE EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.REFNO=CLLOSS.REFNO AND CLDED.ID=CLLOSS.PAYMENT)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0  and Claim.CType<>'C' and Claim.CStatus<>'R' and Claim.PCStatus<>'R'        
AND pClaim.CType<>'C' AND PCLAIM.CStatus='C' AND PCLAIM.PCStatus='A'

)        
        
      
