CREATE FUNCTION CLAIM_SETTLE_BY_DETAIL_LOSS_PAYMENT(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                            
RETURNS TABLE                             
AS RETURN (                                     
SELECT            
 Claim.ADate as Date, CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLLOSS.REFNO, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY, CCALC.RATE, CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,                      
(Case When Claim.CType<>'C' Then (CLLOSS.AMOUNT)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100 else 0 end) as CLAIM_SETTLE,      
(Case When Claim.CType<>'C' Then (CLLOSS.AMOUNT)*CCALC.SHARE/100 else 0 end) as GROSS_CLAIM_SETTLE,    
(Case When Claim.CType<>'C' Then ((CLLOSS.AMOUNT)*CCALC.SHARE/100)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRSHARE/100) else 0 end) as CLAIM_SETTLE_NET    
      
from Claim 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
INNER JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS WHERE EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.REFNO=CLLOSS.REFNO AND CLDED.ID=CLLOSS.PAYMENT)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)
Left Join Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
Where Claim.CStatus in ('C','A') and Claim.CType in ('N','E','C') and Claim.PCstatus in ('','A') and Claim.ADate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and NClaim.CSeqNo is null
            
UNION ALL            
            
SELECT            
  Claim.ADate as Date, PCLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLLOSS.REFNO, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY, CCALC.RATE, PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                      
-(Case When pClaim.CType<>'C' Then (CLLOSS.AMOUNT)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100 else 0 end) as CLAIM_SETTLE,      
-(Case When pClaim.CType<>'C' Then (CLLOSS.AMOUNT)*CCALC.SHARE/100 else 0 end) as GROSS_CLAIM_SETTLE,    
-(Case When pClaim.CType<>'C' Then ((CLLOSS.AMOUNT)*CCALC.SHARE/100)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRSHARE/100) else 0 end) as CLAIM_SETTLE_NET    
from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
INNER JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS WHERE EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.REFNO=CLLOSS.REFNO AND CLDED.ID=CLLOSS.PAYMENT)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)   
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)
Where Claim.CStatus in ('C','A') and Claim.CType in ('N','E','C') and Claim.PCstatus in ('','A') and Claim.ADate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and pClaim.CSeqNo<Claim.CSeqNo
)                              
  
go
DROP  FUNCTION CLAIM_CLOSE_BY_DETAIL_LOSS_PAYMENT
GO
CREATE FUNCTION CLAIM_CLOSE_BY_DETAIL_LOSS_PAYMENT(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                    
RETURNS TABLE                     
AS RETURN (                             
SELECT     

Case When ((Claim.Cstatus='C' and Claim.PCStatus='R' and Claim.VSeqNo>1) or (Claim.Cstatus='C' and Claim.PCStatus='P') or (Claim.SettledF=1 and Claim.CStatus='C' and Claim.PCStatus='A')) and Claim.CSDate between @P_SDate and @P_EDate Then Claim.CSDate else Claim.ADate end as Date,
 CLAIM.OCNO, CLLOSS.NOC, CLLOSS.PAYMENT, CLLOSS.REFNO, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,              
((CLLOSS.ESTIMATE)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100)     
- (CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then ((CLLOSS.AMOUNT)*CCALC.SHARE/100*(100-CARRHEADER.MSHARE)/100) else 0 end)  AS CLAIM_CLOSE,    
(((CLLOSS.ESTIMATE)*CCALC.SHARE/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100))     
- (CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then (((CLLOSS.AMOUNT)*CCALC.SHARE/100)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100)) else 0 end)  AS CLAIM_CLOSE_NET        
from Claim 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
INNER JOIN (SELECT CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO, MAX(CLLOSS.TOI) AS TOI, MAX(CLLOSS.NOC) as NOC, SUM((CASE WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.ESTIMATE)) as ESTIMATE, SUM((CASE WHEN CLLOSS.STATUS<>'P' THEN 0 WHEN CLLOSS.VAR<=CLLOSS.DECLARED THEN 1 ELSE CLLOSS.DECLARED/CLLOSS.VAR END * CLLOSS.AMOUNT)) as AMOUNT FROM CLLOSS WHERE EXISTS (Select TOP 1 LCALC.CNO from ICALC, LCALC Where ICALC.CURRENCY=CLLOSS.CURRENCY_OC AND ICALC.INO=CLLOSS.INO and ICALC.TOR=LCALC.TOR and LCALC.CNO=CLLOSS.CNO and LCALC.CURRENCY=CLLOSS.CURRENCY) GROUP BY CLLOSS.CNO, CLLOSS.PAYMENT, CLLOSS.CURRENCY, CLLOSS.REFNO) CLLOSS ON (CLLOSS.CNO=CCALC.CNO AND CLLOSS.CURRENCY=CCALC.CURRENCY) 
LEFT JOIN (SELECT CNO, ID, CURRENCY, REFNO, SUM(ESTAMOUNT) AS ESTAMOUNT, SUM(AMOUNT) AS AMOUNT FROM CLDED GROUP BY CNO, ID, REFNO, CURRENCY) CLDED ON (CLDED.CNO=CLLOSS.CNO AND CLDED.CURRENCY=CLLOSS.CURRENCY AND CLDED.REFNO=CLLOSS.REFNO AND CLDED.ID=CLLOSS.PAYMENT)
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)    
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)
Where Claim.PSettledF=0 and    
(    
(Claim.CType='C' and Claim.CStatus not in ('R','P','T') and Claim.ADate Between @P_SDate and @P_EDate) Or    
(Claim.Cstatus='C' and Claim.PCStatus='R' and Claim.VSeqNo>1 and Claim.CSDate Between @P_SDate and @P_EDate) Or    
(Claim.Cstatus='C' and Claim.PCStatus='P' and Claim.CSDate Between @P_SDate and @P_EDate) Or    
(Claim.SettledF=1 and Claim.CStatus in ('C','A') and Claim.PCStatus='' and Claim.ADate Between @P_SDate and @P_EDate) or    
(Claim.SettledF=1 and Claim.CStatus='C' and Claim.PCStatus='A' and Claim.CSDate Between @P_SDate and @P_EDate)    
)    
)    



GO

