CREATE FUNCTION CLAIM_REGISTER_BY_DETAIL_LOSS_EXPENSE(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                        
RETURNS TABLE                         
AS RETURN (                                 
Select         
 Claim.RegDate as Date, CLAIM.OCNO, CLCOST.CCTYPE, CLCOST.ID AS PAYMENT, CLCOST.REFNO, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,                  
 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(100-CARRHEADER.MSHARE)/100
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )
 AS CLAIM_REGISTER,        
 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )
 AS CLAIM_REGISTER_NET     
from Claim 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
INNER JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) CLCOST ON (CLCOST.CNO=CCALC.CNO AND CLCOST.CURRENCY=CCALC.CURRENCY) 
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)     
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and Claim.CType<>'C' and Claim.Cstatus<>'R' and Claim.PCStatus<>'R'        

        
UNION ALL        

Select         
 Claim.RegDate as Date, CLAIM.OCNO, CLCOST.CCTYPE, CLCOST.ID AS PAYMENT, CLCOST.REFNO, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY,PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                   
 -(
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(100-CARRHEADER.MSHARE)/100
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )
 AS CLAIM_REGISTER,        
 -(
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )
 AS CLAIM_REGISTER_NET     
from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
INNER JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) CLCOST ON (CLCOST.CNO=CCALC.CNO AND CLCOST.CURRENCY=CCALC.CURRENCY) 
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)
Where Claim.RegDate Between @P_SDate and @P_EDate and Claim.pSettledF=0  and Claim.CType<>'C' and Claim.CStatus<>'R' and Claim.PCStatus<>'R'        
AND pClaim.CType<>'C' and not (PCLAIM.CStatus='C' AND PCLAIM.PCStatus='P')

UNION ALL

SELECT     
 Claim.RegDate as Date, CLAIM.OCNO, CLCOST.CCTYPE, CLCOST.ID AS PAYMENT, CLCOST.REFNO, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY,PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                   

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(100-CARRHEADER.MSHARE)/100
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )
 -(
	CASE WHEN PCLAIM.SettledF=1 and PCLAIM.CStatus in ('C','A') and PCLAIM.PCStatus in ('','A') and PCLAIM.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(100-CARRHEADER.MSHARE)/100
		 +
		 -- EXPENSE_OS
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
	 )
	 Else 0 end
  )
  AS CLAIM_REGISTER,        

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100)
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )
 -(
	CASE WHEN PCLAIM.SettledF=1 and PCLAIM.CStatus in ('C','A') and PCLAIM.PCStatus in ('','A') and PCLAIM.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRSHARE/100)
		 +
		 -- EXPENSE_OS
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
	 )
	 Else 0 end
  )
  AS CLAIM_REGISTER_NET

from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
