from Claim 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
INNER JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) CLCOST ON (CLCOST.CNO=CCALC.CNO AND CLCOST.CURRENCY=CCALC.CURRENCY) 
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)     
Left Join Claim NClaim On (NClaim.pCNO=Claim.CNO and NClaim.CSeqNo=Claim.CSeqNo)
Where Claim.CStatus in ('C','A') and Claim.CType in ('N','E','C') and Claim.PCstatus in ('','A') and Claim.ADate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and NClaim.CSeqNo is null
            
UNION ALL            
            
SELECT            
  Claim.ADate as Date, PCLAIM.OCNO, CLCOST.CCTYPE, CLCOST.ID AS PAYMENT, CLCOST.REFNO, PCLAIM.ANO, CLAIM.CNO AS CCNO, PCLAIM.CNO, CCALC.CURRENCY, CCALC.RATE, PCLAIM.TOC, ACCEPTANCE.BRANCH, PCLAIM.ISTYPE, PCLAIM.CLAIMNO,                      
- (Case When PCLAIM.CType<>'C' Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(100-CARRHEADER.MSHARE)/100
		 +
		 -- EXPENSE_OS
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
	 )
	 Else 0 end
  ) as CLAIM_SETTLE,      
- (Case When PCLAIM.CType<>'C' Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRSHARE/100) 
		 +
		 -- EXPENSE_OS
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
	 )
	 Else 0 end
   ) as CLAIM_SETTLE_NET    
from Claim 
INNER JOIN CLAIM PCLAIM ON (PCLAIM.CNO=CLAIM.PCNO) 
INNER JOIN CCALC ON (CCALC.CNO=PCLAIM.CNO) 
INNER JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) CLCOST ON (CLCOST.CNO=CCALC.CNO AND CLCOST.CURRENCY=CCALC.CURRENCY) 
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=PCLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=PCLAIM.CNO)        
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=PCLAIM.ANO)     
Where Claim.CStatus in ('C','A') and Claim.CType in ('N','E','C') and Claim.PCstatus in ('','A') and Claim.ADate Between @P_SDate and @P_EDate and Claim.pSettledF=0 and pClaim.CSeqNo<Claim.CSeqNo
)                              
  
go
DROP  FUNCTION CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE
GO
CREATE FUNCTION CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                    
RETURNS TABLE                     
AS RETURN (                             
SELECT     

Case When ((Claim.Cstatus='C' and Claim.PCStatus='R' and Claim.VSeqNo>1) or (Claim.Cstatus='C' and Claim.PCStatus='P') or (Claim.SettledF=1 and Claim.CStatus='C' and Claim.PCStatus='A')) and Claim.CSDate between @P_SDate and @P_EDate Then Claim.CSDate else Claim.ADate end as Date,
 CLAIM.OCNO, CLCOST.CCTYPE, CLCOST.ID AS PAYMENT, CLCOST.REFNO, CLAIM.ANO, CLAIM.CNO AS CCNO, CLAIM.CNO, CCALC.CURRENCY,CLAIM.TOC, ACCEPTANCE.BRANCH, CLAIM.ISTYPE, CLAIM.CLAIMNO,              

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)
 )  AS CLAIM_CLOSE_LOSS,

 (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)
	 )
	 Else 0 end
 )  AS CLAIM_CLOSE_SETTLED,    

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_GROSS,    

 (
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 -- EXPENSE_OS
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_OWNEXPENSE,    

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(100-CARRHEADER.MSHARE)/100
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(100-CARRHEADER.MSHARE)/100
		 +
		 -- EXPENSE_OS
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE,    

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*((CARRHEADER.ERETENTION+CARRHEADER.EFRSHARE)/100+RARRHEADER.SPRSHARE/100) 
	 +
	 -- EXPENSE_OS
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*((CARRHEADER.RETENTION+CARRHEADER.FRSHARE)/100+RARRHEADER.SPRSHARE/100) 
		 +
		 -- EXPENSE_OS
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=0 AND CLCOST.CESSIONF=0 THEN 100 ELSE 0 END)/100) 
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_NET,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.EDAmount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.DAmount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_DECREE,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.ECAmount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.CAmount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_BPPDAN,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.EXPAmount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.XPAmount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_MAIPARK,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.EQAmount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.QAmount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_QUOTASHARE,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.ESP1Amount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.SP1Amount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_SURPLUS1,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.ESP2Amount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.SP2Amount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_SURPLUS2,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.ESP3Amount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.SP3Amount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_SURPLUS3,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.EAAmount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.AAmount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_AUTOFAC,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.ETAMOUNT<>0 THEN (CARRHEADER.EFAmount)/CARRHEADER.ETAMOUNT ELSE 0 END)
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CASE WHEN CARRHEADER.TAMOUNT<>0 THEN (CARRHEADER.FAmount)/CARRHEADER.TAMOUNT ELSE 0 END)
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_FACULTATIVE,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL1ESHARE)/100
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL1SHARE)/100
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_XOL1,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL2ESHARE)/100
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL2SHARE)/100
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_XOL2,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL3ESHARE)/100
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL3SHARE)/100
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_XOL3,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL4ESHARE)/100
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL4SHARE)/100
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_XOL4,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL5ESHARE)/100
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL5SHARE)/100
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_XOL5,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL6ESHARE)/100
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL6SHARE)/100
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_XOL6,

 (
	 (CLCOST.ESTIMATE*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL7ESHARE)/100
 )

- (
	CASE WHEN Claim.SettledF=1 and Claim.Cstatus in ('C','A') and Claim.PCStatus in ('','A') and Claim.CType in ('N','E') Then 
	 (
		 (CLCOST.AMOUNT*(CASE WHEN CLCOST.CONTRIBUTIONF=1 THEN CCALC.SHARE ELSE (CASE WHEN CLCOST.CESSIONF=1 THEN 100 ELSE 0 END)  END)/100)*(CARRHEADER.XL7SHARE)/100
	 )
	 Else 0 end
  )  AS CLAIM_CLOSE_XOL7

from Claim 
INNER JOIN CCALC ON (CCALC.CNO=CLAIM.CNO) 
INNER JOIN (SELECT CLCOST.CNO, CLCOST.RefNo, MAX(CAST(CLCOST.ContributionF as Integer)) as CONTRIBUTIONF, MAX(CAST(CLCOST.CESSIONF as Integer)) as CESSIONF, CLCOST.CCTYPE, CLCOST.ID, CLCOST.CURRENCY, SUM(CLCOST.ESTAMOUNT) as ESTIMATE, SUM(CLCOST.AMOUNT) as AMOUNT FROM CLCOST WHERE CLCOST.STATUS='P' GROUP BY CLCOST.CNO, CLCOST.ID, CLCOST.Currency, CLCost.RefNo, CLCOST.CCTYPE) CLCOST ON (CLCOST.CNO=CCALC.CNO AND CLCOST.CURRENCY=CCALC.CURRENCY) 
INNER JOIN ACCEPTANCE ON (ACCEPTANCE.ANO=CLAIM.ANO) 
INNER JOIN CARRHEADER ON (CARRHEADER.CNO=CLAIM.CNO)    
INNER JOIN RARRHEADER ON (RARRHEADER.ANO=CLAIM.ANO)
Where Claim.PSettledF=0 and    
(    
(Claim.CType='C' and Claim.CStatus not in ('R','P','T') and Claim.ADate Between @P_SDate and @P_EDate) Or    
(Claim.Cstatus='C' and Claim.PCStatus='R' and Claim.VSeqNo>1 and Claim.CSDate Between @P_SDate and @P_EDate) Or    
(Claim.Cstatus='C' and Claim.PCStatus='P' and Claim.CSDate Between @P_SDate and @P_EDate) Or    
(Claim.SettledF=1 and Claim.CStatus in ('C','A') and Claim.PCStatus='' and Claim.ADate Between @P_SDate and @P_EDate) or    
(Claim.SettledF=1 and Claim.CStatus='C' and Claim.PCStatus='A' and Claim.CSDate Between @P_SDate and @P_EDate)    
)    
)    

GO


DROP FUNCTION R_CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE
GO
CREATE FUNCTION R_CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE(@P_SDate as smalldatetime, @P_EDate as  smalldatetime)                    
RETURNS @R_CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE TABLE (ID varchar(10), DocNo varchar(50), Type varchar(2), ANO int, CNO int, OCNO int, REFNO varchar(50), Description varchar(255), Currency varchar(10), TOC varchar(10), Amount Float)      
AS      
BEGIN      
      
Declare @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE Table(Payment varchar(10), CNO int, ANO int, OCNO int, Currency varchar(10), TOC varchar(10), ISType varchar(2), ClaimNo varchar(20), Loss_Close Float, Gross_Close Float, Settled_Close Float, Expense_Close Float, BPPDAN_Close Float, MAIPARK_Close Float, DECREE_Close Float, QUOTASHARE_Close Float, SURPLUS1_Close Float, SURPLUS2_Close Float, SURPLUS3_Close Float, AUTOFAC_Close Float, XOL1_Close Float, XOL2_Close Float, XOL3_Close Float, XOL4_Close Float, XOL5_Close Float, XOL6_Close Float, XOL7_Close Float, FACULTATIVE_Close Float)      

insert into @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE      
Select 
O.Payment, O.CNO, O.ANO, O.OCNO, O.Currency, O.TOC, O.ISType, O.ClaimNo
, O.CLAIM_CLOSE_LOSS as Loss_Close
, O.CLAIM_CLOSE_SETTLED as Settled_Close
, O.CLAIM_CLOSE_GROSS as Gross_Close
, O.CLAIM_CLOSE_OWNEXPENSE as Expense_Close
, O.CLAIM_CLOSE_BPPDAN as BPPDAN_Close
, O.CLAIM_CLOSE_MAIPARK as MAIPARK_Close
, O.CLAIM_CLOSE_DECREE as DECREE_Close
, O.CLAIM_CLOSE_QUOTASHARE as QUOTASHARE_Close
, O.CLAIM_CLOSE_SURPLUS1 as SURPLUS1_Close
, O.CLAIM_CLOSE_SURPLUS2 as SURPLUS2_Close
, O.CLAIM_CLOSE_SURPLUS3 as SURPLUS3_Close
, O.CLAIM_CLOSE_AUTOFAC as AUTOFAC_Close
, O.CLAIM_CLOSE_XOL1 as XOL1_Close
, O.CLAIM_CLOSE_XOL2 as XOL2_Close
, O.CLAIM_CLOSE_XOL3 as XOL3_Close
, O.CLAIM_CLOSE_XOL4  as XOL4_Close
, O.CLAIM_CLOSE_XOL5 as XOL5_Close
, O.CLAIM_CLOSE_XOL6 as XOL6_Close
, O.CLAIM_CLOSE_XOL7 as XOL7_Close
, O.CLAIM_CLOSE_FACULTATIVE as FACULTATIVE_Close
from CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE(@P_SDATE, @P_EDATE) O
      

-- INWARD BUSINESS      
Insert into @R_CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE            
select O.Payment as ID, '' as DocNo, Case When O.ISType in ('C','L') then 'DI' else (Case When O.ISType in ('I') then 'IC' else (Case When O.ISType in ('R') then 'IR' else 'IT' end) end) end as Type, O.ANO, O.CNO, O.OCNO, O.CLAIMNO as REFNO, '--' as Description, O.CURRENCY, O.TOC, SUM(O.Gross_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O, RArrheader R Where R.ANO=O.ANO
GROUP BY O.Payment, Case When O.ISType in ('C','L') then 'DI' else (Case When O.ISType in ('I') then 'IC' else (Case When O.ISType in ('R') then 'IR' else 'IT' end) end) end, O.ANO, O.CNO, O.OCNO, O.CLAIMNO, O.CURRENCY, O.TOC        

Insert into @R_CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE  
select O.Payment as ID, '' as DocNo, 'CF' as Type, O.ANO, O.CNO, O.OCNO, O.CLAIMNO as REFNO, '--' as Description, O.CURRENCY, O.TOC, SUM(O.Gross_Close*-R.MShare/100) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O, RArrheader R Where R.ANO=O.ANO
GROUP BY O.Payment, O.ANO, O.CNO, O.OCNO, O.CLAIMNO, O.CURRENCY, O.TOC        

union All

select O.Payment as ID, '' as DocNo, 'OP' as Type, O.ANO, O.CNO, O.OCNO, O.CLAIMNO as REFNO, '--' as Description, O.CURRENCY, O.TOC, SUM(O.EXPENSE_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O, RArrheader R Where R.ANO=O.ANO
GROUP BY O.Payment, O.ANO, O.CNO, O.OCNO, O.CLAIMNO, O.CURRENCY, O.TOC   
Having SUM(O.EXPENSE_Close)<>0     
      
union all      
      
-- OUTWARD BUSINESS      
-- Compulsory      
select R2.ID, R2.DocNo, 'CP' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.BPPDAN_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.CID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          

      
union all             
      
-- Excess Priority      
select R2.ID, R2.DocNo, 'XP' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.MAIPARK_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.XPID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
      
-- Decree      
        
select R2.ID, R2.DocNo, 'DC' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.DECREE_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.DID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          
      
union all      
      
-- Quota Share        
        
select R2.ID, R2.DocNo, 'QS' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.QUOTASHARE_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.QID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          
        
union all        
        
-- Surplus #1        
        
select R2.ID, R2.DocNo, 'S1' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS1_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP1ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          
        
union all        
        
-- Surplus #2        
        
select R2.ID, R2.DocNo, 'S2' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS2_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP2ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          
        
union all        
        
-- Surplus #3        
        
select R2.ID, R2.DocNo, 'S3' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.SURPLUS3_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.SP3ID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          
        
union all        
        
-- Auto Facultative        
        
select R2.ID, R2.DocNo, 'AF' as Type, O.ANO, O.CNO, O.OCNO, R1.DOCNO as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.AUTOFAC_Close) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join RArrHeader R on (R.ANO=O.ANO)
Left Join Reinsurance R1 on (R1.RID=R.AID)
Left Join RPart R2 on (R2.RNO=R1.RNO)
Inner Join CArrHeader C on (C.CNO=O.CNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, R1.DOCNO, R1.DESCRIPTION, O.CURRENCY, O.TOC          

union all        
        
-- Facultative                
     
select R2.ID, R2.SlipNo as DocNo, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
) as Type,
O.ANO, O.CNO, O.OCNO, R2.SLIPNO as REFNO, 
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description,
O.CURRENCY, O.TOC
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.Loss_Close*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				CArrHeader.ETAmount*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.Settled_Close*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 Then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)	 
Where R1.FullCoverF=1 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
AND O.FACULTATIVE_Close<>0
GROUP BY R2.ID, R2.SlipNo, O.ANO, O.CNO, O.OCNO, R2.SLIPNO, O.CURRENCY, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
),
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
),
O.TOC        

union all

select R2.ID, R2.SlipNo as DocNo, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
) as Type,
O.ANO, O.CNO, O.OCNO, R2.SLIPNO as REFNO, 
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
) as Description,
O.CURRENCY, O.TOC
, SUM(
	Case 
	When CArrHeader.ETAmount<>0 then
		O.Loss_Close*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(CArrheader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				CArrHeader.ETAmount*(CASE WHEN CCALC.LOSS<>0 THEN LCALC.LOSS/CCALC.LOSS ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ CArrHeader.ETAmount
	Else
		0
	End
	-
	Case 
	When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)<>0 then
		O.Settled_Close*
		Case When R1.Excess<>0 or R1.Limit<>0 Then   
		 Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>R1.Excess*R1.RateL Then 
			Case When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)>(R1.Excess+R1.Limit)*R1.RateL Then
				(R1.Limit*R1.RateL)*(R1.Share)/100*R2.Share/100
			Else	
				(coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)-R1.Excess*R1.RateL)*(R1.Share)/100*R2.Share/100
			End
		 Else	
			0
		 End
		Else
			Case
			When coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100>R1.Retention*R1.RateL or R1.Retention=0 then
				coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)*(CASE WHEN Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY)<>0 THEN Coalesce(PLCALC.INDEMNITY,LCALC.INDEMNITY)/Coalesce(PCCALC.INDEMNITY,CCALC.INDEMNITY) ELSE 0 END)*(R1.Share)/100*R2.Share/100-R1.Retention*R1.RateL
			Else
				0
			End
		End*(R1.Share-R1.JPShare)/R1.Share
		/ coalesce(pCArrHeader.TAmount,CArrHeader.TAmount)
	Else
		0
	End
) AS Amount
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join Acceptance A on (A.ANO=O.ANO)
Inner Join RArrHeader R on (R.ANO=O.ANO)
Inner Join Claim C on (C.CNO=O.CNO)
Left Join Claim NClaim On (NClaim.pCNO=C.CNO and NClaim.CSeqNo=C.CSeqNo)
Left Join Claim pClaim on (pClaim.CNO=C.pCNO and ((C.CSTATUS in ('P','T')) OR (C.CSTATUS IN ('A') AND C.ADATE>@P_EDATE) OR (C.CSTATUS IN ('C') AND (CASE WHEN NCLAIM.CSEQNO IS NULL AND C.ADATE IS NOT NULL AND C.PCSTATUS<>'P' THEN C.ADATE ELSE C.CSDATE END)>@P_EDATE)))
Inner Join CArrheader on (CArrHeader.CNO=C.CNO)
Left Join CArrheader pCArrHeader on (pCArrHeader.CNO=pClaim.CNO)
Inner Join RarrDet R1 on (R1.ANO=O.ANO)
Inner Join FPart R2 on (R2.ANO=R1.ANO and R2.FID=R1.FID)
Inner Join FPartDet on (FPartDet.ANO=R2.ANO AND FPartDet.FID=R2.FID AND FPartDet.ID=R2.ID)

Cross Apply
(
	SELECT CCALC.CNO, SUM((CCALC.LOSS-CCALC.EDEDUCTIBLE-CCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((CCALC.CLAIM-CCALC.DEDUCTIBLE-CCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM CCALC
	Where CCALC.CNO=C.CNO
	GROUP BY CCALC.CNO
) CCALC 

Cross Apply
(
	SELECT LCALC.CNO, LCALC.TOR, SUM((LCALC.LOSS-LCALC.EDEDUCTIBLE-LCALC.ESALVAGE)*CCALC.RATE) AS LOSS, SUM((LCALC.INDEMNITY-LCALC.DEDUCTIBLE-LCALC.SALVAGE)*CCALC.RATE) AS INDEMNITY
	FROM LCALC, CCALC, COL
	WHERE CCALC.CNO=C.CNO AND CCALC.CNO=LCALC.CNO AND CCALC.CURRENCY=LCALC.CURRENCY
	AND COL.COL=C.COL AND COL.TOR=LCALC.TOR AND EXISTS (Select RateCov.Code from RateCov Where RateCov.Code=FPartDet.Code AND RateCov.TOR=LCALC.TOR)
	GROUP BY LCALC.CNO, LCALC.TOR
) LCALC

Outer Apply
(
	SELECT PCCALC.CNO, SUM((PCCALC.LOSS-PCCALC.EDEDUCTIBLE-PCCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PCCALC.CLAIM-PCCALC.DEDUCTIBLE-PCCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM CCALC PCCALC
	WHERE PCCALC.CNO=pClaim.CNO
	GROUP BY PCCALC.CNO
) PCCALC 


Outer Apply
(
	SELECT PLCALC.CNO, PLCALC.TOR, SUM((PLCALC.LOSS-PLCALC.EDEDUCTIBLE-PLCALC.ESALVAGE)*PCCALC.RATE) AS LOSS, SUM((PLCALC.INDEMNITY-PLCALC.DEDUCTIBLE-PLCALC.SALVAGE)*PCCALC.RATE) AS INDEMNITY
	FROM LCALC PLCALC, CCALC PCCALC
	WHERE PLCALC.CNO=pClaim.CNO AND PLCALC.TOR=LCALC.TOR AND PCCALC.CNO=PLCALC.CNO AND PCCALC.CURRENCY=PLCALC.CURRENCY
	GROUP BY PLCALC.CNO, PLCALC.TOR
) PLCALC

Where R1.FullCoverF=0 and (R1.Share)<>0 and R1.Status<>'O' 
AND ((R1.SDATE<=C.LOSSDATE AND A.ExclusiveF=1) or ((R1.SDATE<C.LOSSDATE or (R1.SDATE=C.LOSSDATE AND A.STIME<=C.LOSSTIME)) AND A.ExclusiveF=0))         
AND ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE AND A.ExclusiveF=1) or ((dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))>C.LOSSDATE or (dbo.fn_Get_ExtPeriodDate(A.ExtRPeriod, 0, dbo.fn_Get_ExtPeriodDate(A.ExtPeriod, A.ExtPeriodInDaysF, R1.EDATE))=C.LOSSDATE AND A.ETIME>C.LOSSTIME)) AND A.ExclusiveF=0))        
AND O.FACULTATIVE_Close<>0
GROUP BY R2.ID, R2.SlipNo, O.ANO, O.CNO, O.OCNO, R2.SLIPNO, O.CURRENCY, 
(
Case 
When R1.RType in ('QS') Then 'QS'
When R1.RType in ('S1','S2','S3') Then R1.RType
When R1.Rtype in ('AF') Then 'AF'
Else 'FO' End
),
(
Case 
When R1.RType in ('QS') Then 'Quota Share '
When R1.RType in ('S1','S2','S3') Then 'Surplus '
When R1.Rtype in ('AF') Then 'Auto Facultative '
Else 'Facultative ' End +Cast(year(R1.SDate) as varchar(100))
),
O.TOC        

union all        
        
-- Excess Of Loss #Layer 1        
        
select R2.ID, R2.DocNo, 'X1' as Type, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL1ID) as REFNO, R1.DESCRIPTION, O.CURRENCY, O.TOC, SUM(coalesce(R2.SHARE,100)/100*O.XOL1_Close) AS Amount        
from @CLAIM_CLOSE_BY_DETAIL_LOSS_EXPENSE O
Inner Join Claim on (Claim.CNO=O.CNO)
Inner Join CArrHeader R on (R.CNO=Claim.CNO)
Left Join CArrHeader pR on (pR.CNO=Claim.pCNO)
Inner Join Reinsurance R1 on (R1.RID=coalesce(R.XL1ID, pR.XL1ID))
Inner Join RPart R2 on (R2.RNO=R1.RNO)
GROUP BY R2.ID, R2.DocNo, O.ANO, O.CNO, O.OCNO, coalesce(R1.DOCNO, R.XL1ID), R1.DESCRIPTION, O.CURRENCY, O.TOC        
        
union all        
        
